BEGIN;

-- 63 topics porteurs d'un angle (traitement/prévention)
UPDATE "health_topics" SET "treatmentSummary"='L''abcès dentaire est une infection qui provoque une accumulation de pus, avec une douleur souvent intense et parfois un gonflement. C''est une urgence dentaire : il ne disparaît pas seul et peut s''étendre. Une consultation rapide auprès d''un chirurgien-dentiste est nécessaire pour traiter l''infection et la dent en cause.', "treatmentSteps"='Consulter rapidement un chirurgien-dentiste dès l''apparition d''une douleur forte, d''un gonflement ou d''un goût inhabituel dans la bouche.
Décrire les symptômes et laisser le praticien examiner la dent, au besoin avec une radiographie.
Suivre la prise en charge proposée pour évacuer l''infection et traiter la dent concernée.
Consulter sans délai en cas de fièvre, de gonflement du visage ou de difficulté à avaler ou respirer.
Assurer un suivi et renforcer l''hygiène bucco-dentaire pour éviter une récidive.', "treatmentSummaryAr"='الخراج السني عدوى تسبب تجمّع القيح، مع ألم غالبا شديد وأحيانا تورم. إنه حالة طارئة في طب الأسنان: لا يزول وحده وقد ينتشر. تلزم استشارة سريعة لطبيب الأسنان لمعالجة العدوى والسن المسبب لها.', "treatmentStepsAr"='استشر طبيب أسنان بسرعة فور ظهور ألم قوي أو تورم أو طعم غير معتاد في الفم.
صف الأعراض ودع الطبيب يفحص السن، بصورة إشعاعية عند الحاجة.
اتبع الرعاية المقترحة لتصريف العدوى ومعالجة السن المعني.
استشر دون تأخير في حال الحمى أو تورم الوجه أو صعوبة البلع أو التنفس.
احرص على المتابعة وتعزيز نظافة الفم والأسنان لتفادي الانتكاس.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-dents', 'carie-dentaire', 'gingivite']::text[] WHERE "slug"='abces-dentaire';
UPDATE "health_topics" SET "treatmentSummary"='L''acné se traite selon sa sévérité, avec des soins locaux adaptés et, dans les formes plus marquées, un traitement prescrit et suivi par le dermatologue. Une routine douce, éviter de percer les lésions et la patience sont essentiels : les résultats prennent plusieurs semaines. Le médecin oriente le traitement selon votre peau.', "treatmentSteps"='Nettoyer la peau en douceur, éviter les produits agressifs et de percer les boutons.
Consulter un médecin généraliste ou un dermatologue pour évaluer la sévérité.
Suivre le traitement local ou général prescrit, avec régularité.
Laisser le temps agir : les effets apparaissent après plusieurs semaines.
Dermatologue pour l''acné sévère, cicatricielle ou résistante.', "treatmentSummaryAr"='يُعالَج حبّ الشباب حسب شدّته، بعناية موضعية مناسبة، وفي الأشكال الأوضح علاجٌ يصفه طبيب الجلد ويتابعه. الروتين اللطيف، تجنّب عصر البثور والصبر أساسية: تحتاج النتائج عدّة أسابيع. يوجّه الطبيب العلاج حسب بشرتك.', "treatmentStepsAr"='تنظيف البشرة بلطف، تجنّب المنتجات القاسية وعصر البثور.
استشارة طبيب عام أو طبيب جلد لتقييم الشدّة.
الالتزام بالعلاج الموضعي أو العام الموصوف بانتظام.
إعطاء الوقت للعلاج: تظهر النتائج بعد عدّة أسابيع.
طبيب الجلد لحبّ الشباب الشديد أو المُخلِّف للندبات أو المقاوِم.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['demangeaisons', 'eczema', 'chute-de-cheveux']::text[] WHERE "slug"='acne';
UPDATE "health_topics" SET "treatmentSummary"='Les acouphènes sont des sons (bourdonnements, sifflements) perçus sans source extérieure. Ils sont fréquents et rarement graves, mais peuvent gêner le sommeil et la concentration. La prise en charge commence par un bilan pour en rechercher la cause, puis vise à réduire la gêne et à mieux vivre avec, sous suivi d''un professionnel.', "treatmentSteps"='Consulter un médecin ORL pour un examen de l''audition et la recherche d''une cause éventuelle.
Protéger ses oreilles du bruit fort et limiter l''exposition prolongée aux sons intenses.
Mettre en place, avec le professionnel, des approches pour réduire la gêne et détourner l''attention du bruit.
Prendre en compte le stress et le sommeil, qui peuvent amplifier la perception des acouphènes.
Consulter rapidement si les acouphènes sont soudains, d''un seul côté ou accompagnés d''une baisse d''audition ou de vertiges.', "treatmentSummaryAr"='الطنين هو أصوات (أزيز أو صفير) تُسمع دون مصدر خارجي. وهو شائع ونادرا ما يكون خطيرا، لكنه قد يعيق النوم والتركيز. تبدأ الرعاية بتقييم للبحث عن السبب، ثم تهدف إلى تخفيف الانزعاج والتأقلم معه، تحت متابعة مختص.', "treatmentStepsAr"='استشر طبيب أنف وأذن وحنجرة لفحص السمع والبحث عن سبب محتمل.
احمِ أذنيك من الضجيج القوي وقلّل التعرض المطوّل للأصوات الشديدة.
اعتمد مع المختص أساليب لتخفيف الانزعاج وصرف الانتباه عن الصوت.
خذ بعين الاعتبار التوتر والنوم، إذ قد يضخّمان الإحساس بالطنين.
استشر بسرعة إذا كان الطنين مفاجئا أو في أذن واحدة أو مصحوبا بتراجع السمع أو الدوار.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['vertiges', 'stress']::text[] WHERE "slug"='acouphenes';
UPDATE "health_topics" SET "treatmentSummary"='Une allergie est une réaction excessive du système immunitaire à une substance habituellement inoffensive. Les symptômes varient (nez, yeux, peau, respiration) et peuvent être gênants. La prise en charge repose sur l''identification des déclencheurs, leur évitement et un suivi médical ; une réaction sévère est une urgence vitale.', "treatmentSteps"='Noter les symptômes et les circonstances de survenue pour aider à repérer les déclencheurs possibles.
Consulter un médecin, qui pourra orienter vers un bilan allergologique si nécessaire.
Réduire l''exposition aux facteurs identifiés dans l''environnement et le quotidien.
Suivre le plan de prise en charge défini avec le professionnel de santé.
Appeler les secours immédiatement en cas de gonflement du visage, de gêne à respirer ou de malaise : ce sont des signes de réaction grave.', "treatmentSummaryAr"='الحساسية تفاعل مفرط من الجهاز المناعي تجاه مادة غير ضارة عادة. تتنوع الأعراض (الأنف، العينان، الجلد، التنفس) وقد تكون مزعجة. تقوم الرعاية على تحديد المحفزات وتجنّبها ومتابعة طبية؛ والتفاعل الشديد حالة طارئة تهدد الحياة.', "treatmentStepsAr"='دوّن الأعراض وظروف ظهورها للمساعدة في تحديد المحفزات المحتملة.
استشر طبيبا، إذ قد يوجّهك إلى تقييم للحساسية عند الحاجة.
قلّل التعرّض للعوامل المحددة في محيطك وحياتك اليومية.
اتبع خطة الرعاية المحددة مع مختص في الصحة.
اتصل بالإسعاف فورا في حال تورم الوجه أو صعوبة التنفس أو الإغماء: فهذه علامات تفاعل خطير.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['allergie-alimentaire', 'eczema']::text[] WHERE "slug"='allergie';
UPDATE "health_topics" SET "treatmentSummary"='L''anémie se traite après en avoir trouvé la cause, avec un médecin généraliste qui prescrit un bilan sanguin. La prise en charge dépend de l''origine (carence, saignement, maladie). Une alimentation adaptée peut aider, mais toute supplémentation doit être encadrée. L''hématologue intervient pour les formes complexes. Une fatigue importante ou un essoufflement nécessitent un avis médical rapide.', "treatmentSteps"='Consulter un médecin devant une fatigue persistante, une pâleur, un essoufflement ou des vertiges, et faire réaliser une prise de sang.
Identifier la cause avec le médecin : carence alimentaire, saignements, ou maladie sous-jacente.
Adopter une alimentation adaptée selon les conseils du médecin, sans se supplémenter seul.
Respecter le suivi prescrit et refaire les contrôles sanguins pour vérifier l''amélioration.
Consulter en urgence en cas d''essoufflement au repos, de douleur thoracique ou de malaise.', "treatmentSummaryAr"='يُعالَج فقر الدم بعد معرفة سببه، مع طبيب عام يصف تحليلًا للدم. يعتمد التدبير على المصدر (نقص، نزيف، مرض). قد تساعد تغذية ملائمة، لكن أي مكمّل يجب أن يكون تحت إشراف. يتدخّل طبيب أمراض الدم في الأشكال المعقّدة. التعب الشديد أو ضيق التنفّس يستدعيان رأيًا طبيًّا سريعًا.', "treatmentStepsAr"='استشر طبيبًا عند تعب مستمر أو شحوب أو ضيق تنفّس أو دوار، وأجرِ تحليلًا للدم.
حدّد السبب مع الطبيب: نقص غذائي، نزيف، أو مرض كامن.
اعتمد تغذية ملائمة وفق نصائح الطبيب، دون تناول مكمّلات بمفردك.
التزم بالمتابعة الموصوفة وأعد التحاليل الدموية للتأكّد من التحسّن.
استشر بشكل عاجل عند ضيق تنفّس أثناء الراحة أو ألم صدري أو إغماء.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['carence-en-fer', 'fatigue']::text[] WHERE "slug"='anemie';
UPDATE "health_topics" SET "treatmentSummary"='L''angine se soigne d''abord par une consultation qui distingue l''origine virale de l''origine bactérienne, souvent à l''aide d''un test de gorge. Le repos, une bonne hydratation et le soulagement de la douleur suffisent la plupart du temps. Un traitement spécifique n''est prescrit par le médecin qu''en cas d''infection bactérienne confirmée, pour éviter les complications.', "treatmentSteps"='Consulter un médecin généraliste ou ORL pour examiner la gorge
Faire un test rapide si le médecin veut distinguer virus et bactérie
Se reposer, bien s''hydrater et soulager la douleur selon l''avis médical
Suivre le traitement prescrit uniquement s''il est jugé nécessaire
Reconsulter en urgence si forte fièvre persistante, difficulté à avaler ou à respirer', "treatmentSummaryAr"='يبدأ علاج التهاب الحلق باستشارة طبية تُميّز بين السبب الفيروسي والسبب البكتيري، غالبًا بمساعدة اختبار سريع للحلق. الراحة والإكثار من شرب السوائل وتخفيف الألم تكفي في أغلب الحالات. لا يصف الطبيب علاجًا خاصًا إلا عند تأكّد العدوى البكتيرية، لتفادي المضاعفات.', "treatmentStepsAr"='استشارة طبيب عام أو أخصائي أنف وأذن وحنجرة لفحص الحلق
إجراء اختبار سريع إذا أراد الطبيب التمييز بين الفيروس والبكتيريا
الراحة وشرب السوائل وتخفيف الألم حسب نصيحة الطبيب
اتباع العلاج الموصوف فقط إذا رأى الطبيب ضرورته
استشارة عاجلة عند حمى شديدة مستمرة أو صعوبة في البلع أو التنفس', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-gorge', 'rhume', 'laryngite']::text[] WHERE "slug"='angine';
UPDATE "health_topics" SET "treatmentSummary"='L''angine de poitrine est un signal d''alerte du cœur qui impose une consultation cardiologique. La prise en charge associe contrôle des facteurs de risque (tabac, cholestérol, tension, diabète), hygiène de vie et suivi spécialisé. L''objectif est de protéger le cœur et de prévenir l''infarctus. Une douleur thoracique intense, prolongée ou au repos impose d''appeler les secours immédiatement.', "treatmentSteps"='Consulter rapidement un médecin devant une douleur ou une oppression dans la poitrine à l''effort.
Réaliser le bilan cardiologique prescrit pour évaluer le cœur et les artères.
Agir sur les facteurs de risque : arrêt du tabac, alimentation, cholestérol, tension, diabète.
Suivre le traitement et les recommandations du cardiologue, avec des contrôles réguliers.
Appeler les secours en urgence si la douleur est intense, prolongée, survient au repos ou s''accompagne d''un malaise.', "treatmentSummaryAr"='الذبحة الصدرية إشارة إنذار من القلب تفرض استشارة طبيب القلب. يجمع التدبير بين ضبط عوامل الخطر (التدخين، الكوليسترول، الضغط، السكري) ونمط حياة صحّي ومتابعة مختصّة. الهدف حماية القلب والوقاية من الاحتشاء. الألم الصدري الشديد أو المطوّل أو أثناء الراحة يفرض الاتّصال بالإسعاف فورًا.', "treatmentStepsAr"='استشر طبيبًا بسرعة عند ألم أو ضغط في الصدر أثناء المجهود.
أجرِ تقييم القلب الموصوف لفحص القلب والشرايين.
تعامل مع عوامل الخطر: الإقلاع عن التدخين، التغذية، الكوليسترول، الضغط، السكري.
اتّبع العلاج وتوصيات طبيب القلب مع فحوص منتظمة.
اتّصل بالإسعاف بشكل عاجل إن كان الألم شديدًا أو مطوّلًا أو حدث أثناء الراحة أو صاحبه إغماء.', "preventionSummary"='L''angine de poitrine traduit un cœur mal irrigué, le plus souvent lié à l''athérosclérose. On réduit fortement le risque en agissant sur les mêmes facteurs que l''infarctus : tabac, tension, cholestérol, diabète et sédentarité. Un médecin évalue votre risque cardiovasculaire et propose un suivi adapté.', "preventionSteps"='Arrêter le tabac, facteur majeur d''athérosclérose coronarienne.
Contrôler tension, cholestérol et diabète avec son médecin.
Adopter une alimentation pauvre en graisses saturées et riche en légumes.
Pratiquer une activité physique régulière adaptée à sa condition.
Consulter sans tarder devant une douleur thoracique à l''effort.', "preventionSummaryAr"='تعبّر الذبحة الصدرية عن ضعف تروية القلب، وغالبًا ما ترتبط بتصلب الشرايين. يمكن خفض الخطر بشكل كبير بالعمل على نفس عوامل الاحتشاء: التدخين، الضغط، الكوليسترول، السكري والخمول. يقيّم الطبيب خطرك القلبي الوعائي ويقترح متابعة ملائمة.', "preventionStepsAr"='الإقلاع عن التدخين، وهو عامل رئيسي لتصلب الشرايين التاجية.
التحكم في الضغط والكوليسترول والسكري بمساعدة الطبيب.
اعتماد تغذية فقيرة بالدهون المشبعة وغنية بالخضروات.
ممارسة نشاط بدني منتظم يلائم حالتك.
استشارة الطبيب دون تأخير عند ألم صدري أثناء المجهود.', "relatedTopicSlugs"=ARRAY['hypercholesterolemie', 'douleur-thoracique']::text[] WHERE "slug"='angine-de-poitrine';
UPDATE "health_topics" SET "treatmentSummary"='L''anxiété se prend en charge en agissant sur l''hygiène de vie (sommeil, activité physique, réduction des excitants), par un accompagnement psychologique comme les thérapies cognitivo-comportementales, et parfois un traitement prescrit et suivi par le médecin. Parler à un professionnel est la première étape ; un psychiatre ou un psychologue accompagne la démarche.', "treatmentSteps"='En parler à un médecin généraliste, premier interlocuteur pour faire le point.
Améliorer sommeil et activité physique, réduire café et excitants.
Envisager un suivi psychologique (thérapie cognitivo-comportementale).
Un traitement peut être proposé et suivi par le médecin si nécessaire.
Psychiatre ou psychologue pour un accompagnement adapté.', "treatmentSummaryAr"='يُتكفَّل بالقلق بالعمل على نمط الحياة (النوم، النشاط البدني، تقليل المنبّهات)، بمرافقة نفسية كالعلاج المعرفي السلوكي، وأحياناً علاجٍ يصفه الطبيب ويتابعه. التحدّث إلى مختصّ هو الخطوة الأولى؛ يرافق الطبيب النفسي أو الأخصائي النفسي هذا المسار.', "treatmentStepsAr"='التحدّث إلى طبيب عام، أول مُحاوِر لتقييم الوضع.
تحسين النوم والنشاط البدني، تقليل القهوة والمنبّهات.
التفكير في مرافقة نفسية (علاج معرفي سلوكي).
قد يُقترح علاجٌ يتابعه الطبيب عند الحاجة.
الطبيب النفسي أو الأخصائي النفسي لمرافقة مناسبة.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['crise-d-angoisse', 'depression', 'insomnie']::text[] WHERE "slug"='anxiete';
UPDATE "health_topics" SET "treatmentSummary"='Les aphtes sont de petites ulcérations douloureuses de la bouche, le plus souvent bénignes et spontanément résolutives en une à deux semaines. La prise en charge vise surtout à soulager la gêne et à identifier d''éventuels facteurs déclenchants. Des aphtes très fréquents, étendus ou persistants justifient l''avis d''un professionnel de santé.', "treatmentSteps"='Repérer d''éventuels facteurs favorisants : certains aliments, un frottement dentaire, la fatigue ou le stress.
Adopter une hygiène buccale douce et privilégier des aliments qui n''irritent pas la lésion pendant la cicatrisation.
Surveiller l''évolution : un aphte isolé disparaît en général en une à deux semaines.
Consulter un professionnel de santé si les aphtes sont récidivants, très nombreux, très douloureux ou durent au-delà de deux semaines.', "treatmentSummaryAr"='القلاع الفموي عبارة عن تقرحات صغيرة مؤلمة في الفم، غالبا حميدة وتلتئم تلقائيا خلال أسبوع إلى أسبوعين. تهدف الرعاية أساسا إلى تخفيف الانزعاج وتحديد العوامل المحفزة المحتملة. أما القلاع المتكرر جدا أو الواسع أو المستمر فيستدعي رأي مختص في الصحة.', "treatmentStepsAr"='تعرّف على العوامل المحفزة المحتملة: بعض الأطعمة، احتكاك سنّي، الإرهاق أو التوتر.
اعتمد نظافة فموية لطيفة وفضّل أطعمة لا تهيّج التقرح أثناء الالتئام.
راقب التطور: القلاع المنعزل يزول عادة خلال أسبوع إلى أسبوعين.
استشر مختصا في الصحة إذا كان القلاع متكررا أو كثير العدد أو شديد الألم أو استمر أكثر من أسبوعين.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-dents']::text[] WHERE "slug"='aphtes';
UPDATE "health_topics" SET "treatmentSummary"='L''apnée du sommeil se confirme par un enregistrement du sommeil, prescrit après consultation d''un médecin. La prise en charge associe hygiène de vie (poids, alcool, tabac) et, selon les cas, un appareillage adapté proposé par un spécialiste du sommeil ou un ORL. L''objectif est de restaurer un sommeil réparateur et de prévenir les risques cardiovasculaires. Une somnolence marquée au volant impose la prudence.', "treatmentSteps"='Consulter un médecin devant des ronflements importants, une somnolence diurne ou des pauses respiratoires signalées par l''entourage.
Réaliser un enregistrement du sommeil pour confirmer le diagnostic et évaluer la sévérité.
Agir sur les facteurs favorisants : surpoids, alcool le soir, tabac, position de sommeil.
Mettre en place le traitement proposé par le spécialiste et en respecter le suivi.
Redoubler de prudence en cas de somnolence au volant et le signaler au médecin.', "treatmentSummaryAr"='يُؤكَّد انقطاع التنفّس أثناء النوم بتسجيل للنوم يُوصف بعد استشارة طبيب. يجمع التدبير بين نمط حياة صحّي (الوزن، الكحول، التدخين) وأحيانًا جهاز ملائم يقترحه أخصّائي النوم أو طبيب الأنف والأذن والحنجرة. الهدف استعادة نوم مريح والوقاية من مخاطر القلب. النعاس الشديد أثناء القيادة يفرض الحذر.', "treatmentStepsAr"='استشر طبيبًا عند شخير قوي أو نعاس نهاري أو توقّفات تنفّسية يلاحظها المحيطون.
أجرِ تسجيلًا للنوم لتأكيد التشخيص وتقييم درجة الخطورة.
تعامل مع العوامل المساعدة: زيادة الوزن، الكحول مساءً، التدخين، وضعية النوم.
طبّق العلاج الذي يقترحه الأخصّائي والتزم بمتابعته.
ضاعف الحذر عند النعاس أثناء القيادة وأبلغ الطبيب بذلك.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['obesite']::text[] WHERE "slug"='apnee-du-sommeil';
UPDATE "health_topics" SET "treatmentSummary"='Arrêter de fumer est le geste le plus bénéfique pour la santé, et les bénéfices apparaissent très vite. Le sevrage est plus facile lorsqu''il est préparé et accompagné. Un professionnel de santé peut proposer un plan adapté, un soutien face aux envies et un suivi pour tenir dans la durée et éviter la rechute.', "treatmentSteps"='Choisir une date d''arrêt et noter ses motivations personnelles pour s''y référer dans les moments difficiles.
En parler à un professionnel de santé (médecin, pharmacien ou tabacologue) pour être accompagné et évaluer les aides disponibles.
Anticiper les situations à risque et préparer des stratégies pour gérer les envies de fumer.
S''appuyer sur son entourage et sur un suivi régulier pour rester motivé.
Ne pas se décourager en cas de rechute : la reprise d''une nouvelle tentative fait partie du parcours, avec l''aide d''un professionnel.', "treatmentSummaryAr"='الإقلاع عن التدخين هو أنفع خطوة للصحة، وتظهر فوائده بسرعة كبيرة. يكون الإقلاع أسهل حين يُحضَّر له ويُواكب. يمكن لمختص في الصحة أن يقترح خطة مناسبة ودعما لمواجهة الرغبة الملحّة ومتابعة للاستمرار وتفادي الانتكاس.', "treatmentStepsAr"='اختر تاريخا للإقلاع ودوّن دوافعك الشخصية للرجوع إليها في اللحظات الصعبة.
تحدّث إلى مختص في الصحة (طبيب أو صيدلي أو أخصائي في التبغ) للمواكبة وتقييم المساعدات المتاحة.
توقّع المواقف الخطرة وحضّر استراتيجيات للتعامل مع الرغبة في التدخين.
استند إلى محيطك وإلى متابعة منتظمة للحفاظ على الحافز.
لا تيأس عند الانتكاس: بدء محاولة جديدة جزء من المسار، بمساعدة مختص.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['addiction', 'stress']::text[] WHERE "slug"='arret-du-tabac';
UPDATE "health_topics" SET "treatmentSummary"='L''arthrose est une usure du cartilage des articulations, fréquente avec l''âge. Elle ne se guérit pas mais se soulage durablement. Le médecin généraliste et le rhumatologue orientent la prise en charge, centrée sur l''activité physique adaptée, la gestion du poids et le maintien de la mobilité au quotidien.', "treatmentSteps"='Consultez un médecin généraliste ou un rhumatologue pour confirmer l''arthrose et évaluer les articulations touchées.
Maintenez une activité physique douce et régulière (marche, natation) pour préserver la mobilité et renforcer les muscles.
Agissez sur le poids si nécessaire, pour réduire les contraintes sur les articulations portantes.
La kinésithérapie peut être proposée pour entretenir la souplesse et soulager les douleurs.
Reconsultez si la douleur devient intense, invalidante ou s''accompagne d''un gonflement important.', "treatmentSummaryAr"='خشونة المفاصل هي تآكل غضروف المفاصل، وتكثر مع التقدّم في السن. لا تُشفى لكن يمكن تخفيفها بشكل دائم. يوجّه الطبيب العام وطبيب الروماتيزم العلاج المتمحور حول نشاط بدني مناسب والتحكم في الوزن والحفاظ على الحركة اليومية.', "treatmentStepsAr"='استشر طبيباً عاماً أو طبيب روماتيزم لتأكيد الخشونة وتقييم المفاصل المصابة.
حافظ على نشاط بدني لطيف ومنتظم (المشي، السباحة) للحفاظ على الحركة وتقوية العضلات.
تحكّم في الوزن عند الحاجة لتقليل الضغط على المفاصل الحاملة.
قد يُقترح العلاج الطبيعي (الترويض) للحفاظ على المرونة وتخفيف الألم.
عاود الاستشارة إذا أصبح الألم شديداً أو معيقاً أو مصحوباً بتورّم كبير.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['douleurs-articulaires', 'osteoporose']::text[] WHERE "slug"='arthrose';
UPDATE "health_topics" SET "treatmentSummary"='L''asthme est une maladie chronique qui se contrôle grâce à un suivi médical régulier et à un traitement de fond adapté par le médecin. Identifier et éviter les facteurs déclenchants est essentiel. Un plan d''action personnalisé aide à réagir aux crises. L''objectif est d''espacer les symptômes et de préserver une respiration normale au quotidien.', "treatmentSteps"='Consulter un médecin ou un pneumologue pour confirmer le diagnostic
Mettre en place le traitement de fond et le plan d''action prescrits
Identifier et éviter les facteurs déclenchants (tabac, allergènes)
Assurer un suivi régulier pour ajuster la prise en charge
Appeler les urgences en cas de crise sévère avec essoufflement important', "treatmentSummaryAr"='الربو مرض مزمن يُتحكَّم فيه بفضل متابعة طبية منتظمة وعلاج أساسي يُكيّفه الطبيب. تحديد العوامل المُحفّزة وتجنّبها أمر أساسي. تساعد خطة عمل شخصية على التعامل مع النوبات. الهدف مباعدة الأعراض والحفاظ على تنفّس طبيعي في الحياة اليومية.', "treatmentStepsAr"='استشارة طبيب أو أخصائي رئة لتأكيد التشخيص
تطبيق العلاج الأساسي وخطة العمل الموصوفَين
تحديد العوامل المُحفّزة وتجنّبها (التدخين، مسببات الحساسية)
ضمان متابعة منتظمة لتعديل طريقة العلاج
الاتصال بالطوارئ عند نوبة شديدة مع ضيق تنفّس كبير', "preventionSummary"='L''asthme ne se prévient pas totalement, car il repose souvent sur un terrain allergique ou familial. On peut cependant réduire nettement la fréquence des crises en identifiant et en évitant les facteurs déclenchants. Le tabac, les allergènes et la pollution jouent un rôle majeur. Un suivi médical régulier permet d''adapter la prévention à chaque personne.', "preventionSteps"='Éviter le tabac et l''exposition à la fumée, dès l''enfance.
Identifier et limiter les allergènes (acariens, poils, pollens).
Aérer et assainir le logement, réduire humidité et moisissures.
Suivre le plan de soins établi avec votre médecin.
Consulter pour un suivi régulier et en cas de gêne respiratoire.', "preventionSummaryAr"='لا يمكن الوقاية من الربو تمامًا لأنه يقوم غالبًا على أرضية تحسّسية أو عائلية. غير أنه يمكن خفض تواتر النوبات بوضوح عبر تحديد العوامل المحفّزة وتجنّبها. ويلعب التدخين والمواد المسبّبة للحساسية والتلوّث دورًا كبيرًا. ويسمح المتابعة الطبية المنتظمة بتكييف الوقاية مع كل شخص.', "preventionStepsAr"='تجنّب التدخين والتعرّض للدخان منذ الطفولة.
تحديد المواد المسبّبة للحساسية والحدّ منها (العث، الوبر، اللقاح).
تهوية المنزل وتنقيته وتقليل الرطوبة والعفن.
اتّباع خطة العلاج المتّفق عليها مع طبيبك.
الاستشارة للمتابعة المنتظمة وعند حدوث ضيق في التنفّس.', "relatedTopicSlugs"=ARRAY['essoufflement', 'toux', 'rhinite-allergique']::text[] WHERE "slug"='asthme';
UPDATE "health_topics" SET "treatmentSummary"=NULL, "treatmentSteps"=NULL, "treatmentSummaryAr"=NULL, "treatmentStepsAr"=NULL, "preventionSummary"='La majorité des accidents vasculaires cérébraux sont évitables en contrôlant leurs facteurs de risque : tension, diabète, cholestérol, tabac et sédentarité. Dépister et traiter l''hypertension est la mesure la plus efficace. Un médecin évalue votre risque global et adapte votre suivi, surtout après 50 ans ou en cas d''antécédents.', "preventionSteps"='Faire surveiller et contrôler sa tension artérielle, premier facteur de risque d''AVC.
Arrêter le tabac et limiter l''alcool.
Équilibrer diabète et cholestérol avec l''aide de son médecin.
Pratiquer une activité physique régulière et manger équilibré.
Consulter en cas de palpitations, une arythmie non traitée augmentant le risque.', "preventionSummaryAr"='يمكن الوقاية من معظم السكتات الدماغية عبر التحكم في عوامل الخطر: الضغط، السكري، الكوليسترول، التدخين والخمول. ويبقى كشف وعلاج ارتفاع الضغط الإجراء الأكثر فعالية. يقيّم الطبيب خطرك الإجمالي ويكيّف متابعتك، خاصة بعد سن الخمسين أو عند وجود سوابق.', "preventionStepsAr"='مراقبة ضغط الدم والتحكم فيه، وهو العامل الأول لخطر السكتة الدماغية.
الإقلاع عن التدخين والحد من الكحول.
ضبط السكري والكوليسترول بمساعدة الطبيب.
ممارسة نشاط بدني منتظم والأكل المتوازن.
استشارة الطبيب عند الخفقان، فعدم علاج اضطراب النظم يزيد الخطر.', "relatedTopicSlugs"=ARRAY[]::text[] WHERE "slug"='avc';
UPDATE "health_topics" SET "treatmentSummary"='Les ballonnements sont une sensation de ventre gonflé, souvent liée à l''alimentation, au transit ou au stress. Ils sont généralement bénins et s''améliorent avec des ajustements simples du mode de vie. Un médecin peut aider à identifier des déclencheurs et écarter une cause sous-jacente lorsque la gêne est fréquente ou persistante.', "treatmentSteps"='Observer les moments d''apparition et repérer les aliments ou situations qui semblent déclencher la gêne.
Manger lentement, à horaires réguliers, et limiter les aliments qui provoquent des gaz selon votre ressenti.
Bouger régulièrement et prêter attention au stress, qui influence la digestion.
Consulter un médecin si les ballonnements sont fréquents, très gênants ou s''accompagnent d''autres symptômes.
Consulter sans tarder en cas de perte de poids, de sang dans les selles ou de douleur intense.', "treatmentSummaryAr"='الانتفاخ هو إحساس بامتلاء البطن، غالبا مرتبط بالتغذية أو حركة الأمعاء أو التوتر. عادة ما يكون حميدا ويتحسن بتعديلات بسيطة في نمط الحياة. يمكن للطبيب المساعدة في تحديد المحفزات واستبعاد سبب كامن عندما يكون الانزعاج متكررا أو مستمرا.', "treatmentStepsAr"='لاحظ أوقات الظهور وحدّد الأطعمة أو الحالات التي يبدو أنها تثير الانزعاج.
تناول الطعام ببطء وفي مواعيد منتظمة، وقلّل الأطعمة المسببة للغازات حسب إحساسك.
مارس الحركة بانتظام وانتبه للتوتر لأنه يؤثر في الهضم.
استشر طبيبا إذا كان الانتفاخ متكررا أو مزعجا جدا أو مصحوبا بأعراض أخرى.
استشر دون تأخير في حال فقدان الوزن أو دم في البراز أو ألم شديد.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['flatulences', 'mal-de-ventre']::text[] WHERE "slug"='ballonnements';
UPDATE "health_topics" SET "treatmentSummary"='La bronchite aiguë est le plus souvent virale et guérit seule en une à trois semaines. Le repos, une bonne hydratation et l''arrêt du tabac favorisent la récupération. La toux peut persister quelque temps sans gravité. Une consultation s''impose si la fièvre est élevée, si l''essoufflement apparaît ou si les symptômes se prolongent, pour écarter une pneumonie.', "treatmentSteps"='Se reposer, s''hydrater et éviter le tabac et la fumée
Soulager la toux selon les conseils du médecin ou du pharmacien
Surveiller l''évolution de la fièvre et de la respiration
Consulter si essoufflement, fièvre élevée ou toux prolongée
Reconsulter rapidement en cas de crachats de sang ou de gêne respiratoire', "treatmentSummaryAr"='التهاب الشعب الهوائية الحاد غالبًا فيروسي ويُشفى وحده في أسبوع إلى ثلاثة أسابيع. الراحة وشرب السوائل والإقلاع عن التدخين تُسرّع التعافي. قد يستمرّ السعال بعض الوقت دون خطورة. تلزم الاستشارة عند حمى مرتفعة أو ظهور ضيق تنفّس أو استمرار الأعراض، لاستبعاد التهاب رئوي.', "treatmentStepsAr"='الراحة وشرب السوائل وتجنّب التدخين والدخان
تخفيف السعال حسب نصيحة الطبيب أو الصيدلي
مراقبة تطوّر الحمى والتنفّس
الاستشارة عند ضيق تنفّس أو حمى مرتفعة أو سعال مطوّل
إعادة الاستشارة بسرعة عند بصق دم أو ضيق في التنفّس', "preventionSummary"='On peut réduire le risque de bronchite en protégeant ses bronches des agressions. La cause la plus fréquente est virale : l''hygiène des mains et l''aération aident. Éviter le tabac et la fumée est essentiel, car ils fragilisent durablement les bronches. La vaccination contre la grippe et certaines infections respiratoires protège les personnes à risque.', "preventionSteps"='Arrêter de fumer et éviter le tabagisme passif.
Se laver les mains et aérer les pièces en saison froide.
Se faire vacciner contre la grippe si vous êtes à risque.
Limiter l''exposition à la pollution et aux poussières irritantes.
Consulter si la toux persiste ou s''accompagne de gêne à respirer.', "preventionSummaryAr"='يمكن خفض خطر التهاب القصبات عبر حماية القصبات من العوامل المؤذية. السبب الأكثر شيوعًا فيروسي، لذا تساعد نظافة اليدين والتهوية. وتجنّب التدخين والدخان أساسي لأنهما يُضعفان القصبات بشكل دائم. ويحمي التلقيح ضد الأنفلونزا وبعض الالتهابات التنفسية الأشخاص المعرّضين للخطر.', "preventionStepsAr"='الإقلاع عن التدخين وتجنّب التدخين السلبي.
غسل اليدين وتهوية الغرف في الفصل البارد.
أخذ لقاح الأنفلونزا إذا كنت من الفئات المعرّضة للخطر.
الحدّ من التعرّض للتلوّث والغبار المهيّج.
الاستشارة إذا استمر السعال أو رافقه ضيق في التنفّس.', "relatedTopicSlugs"=ARRAY['toux', 'essoufflement', 'pneumonie']::text[] WHERE "slug"='bronchite';
UPDATE "health_topics" SET "treatmentSummary"='Les brûlures d''estomac occasionnelles s''atténuent avec des mesures simples : repas plus légers, éviter les aliments qui les déclenchent, ne pas s''allonger juste après manger, réduire tabac et alcool. Si elles sont fréquentes, le médecin évalue la cause et propose un traitement. Un gastro-entérologue intervient si les symptômes persistent.', "treatmentSteps"='Adopter des repas plus légers et éviter les aliments déclencheurs.
Ne pas s''allonger juste après manger ; surélever la tête du lit si besoin.
Réduire tabac et alcool.
Consulter un médecin si les brûlures sont fréquentes ou gênantes.
Gastro-entérologue en cas de symptômes persistants ou de signes d''alerte.', "treatmentSummaryAr"='تخفّ حُرقة المعدة العابرة بتدابير بسيطة: وجبات أخفّ، تجنّب الأطعمة المُحفِّزة، عدم الاستلقاء مباشرة بعد الأكل، تقليل التدخين والكحول. عند تكرّرها، يقيّم الطبيب السبب ويقترح علاجاً. يتدخّل طبيب الجهاز الهضمي إذا استمرّت الأعراض.', "treatmentStepsAr"='اعتماد وجبات أخفّ وتجنّب الأطعمة المُحفِّزة.
عدم الاستلقاء مباشرة بعد الأكل؛ رفع رأس السرير عند الحاجة.
تقليل التدخين والكحول.
استشارة طبيب إذا كانت الحُرقة متكرّرة أو مُزعجة.
طبيب الجهاز الهضمي عند أعراض مستمرّة أو علامات إنذار.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-ventre', 'ballonnements', 'gastrite']::text[] WHERE "slug"='brulures-d-estomac';
UPDATE "health_topics" SET "treatmentSummary"='Une brûlure en urinant évoque souvent une infection urinaire, mais d''autres causes existent. Chez la femme, une consultation rapide est recommandée ; chez l''homme, l''enfant, la femme enceinte ou en cas de fièvre, l''avis médical est prioritaire. Le médecin confirme la cause avant toute prise en charge.', "treatmentSteps"='Consultez un médecin généraliste, surtout en cas de fièvre, de douleurs au dos, de grossesse ou chez l''homme et l''enfant.
Une analyse d''urine peut être demandée pour confirmer l''infection et en préciser la cause.
Buvez suffisamment d''eau pour aider à évacuer les urines.
Suivez la prise en charge indiquée par le médecin jusqu''à son terme.
Consultez en urgence si apparaissent fièvre élevée, douleurs lombaires, frissons ou sang dans les urines.', "treatmentSummaryAr"='غالباً ما يدل الحُرقان عند التبوّل على التهاب بولي، لكن هناك أسباب أخرى. عند المرأة يُنصح باستشارة سريعة، وعند الرجل والطفل والحامل أو مع الحمى تكون الاستشارة الطبية أولوية. يؤكد الطبيب السبب قبل أي علاج.', "treatmentStepsAr"='استشر طبيباً عاماً، خاصة مع الحمى أو ألم الظهر أو الحمل أو عند الرجل والطفل.
قد يُطلب تحليل بول لتأكيد العدوى وتحديد سببها.
اشرب ماءً كافياً للمساعدة على طرد البول.
التزم بالعلاج الذي يحدده الطبيب حتى نهايته.
استشر بشكل عاجل عند ظهور حمى مرتفعة أو ألم أسفل الظهر أو قشعريرة أو دم في البول.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['infection-urinaire', 'colique-nephretique']::text[] WHERE "slug"='brulures-urinaires';
UPDATE "health_topics" SET "treatmentSummary"='Le bruxisme est le fait de serrer ou grincer des dents, souvent la nuit et sans s''en rendre compte. Il peut user les dents et provoquer des douleurs de la mâchoire ou des maux de tête. La prise en charge associe la réduction des tensions, la protection des dents et le traitement des causes, sous supervision d''un professionnel.', "treatmentSteps"='Reconnaître les signes : dents usées, mâchoire douloureuse au réveil, maux de tête ou bruit de grincement signalé par l''entourage.
Consulter un chirurgien-dentiste pour évaluer l''état des dents et de l''articulation de la mâchoire.
Explorer les facteurs contributifs, notamment le stress et les troubles du sommeil, avec un professionnel.
Envisager avec le praticien une protection dentaire adaptée pour limiter l''usure la nuit.
Mettre en place des mesures de détente et un suivi régulier pour surveiller l''évolution.', "treatmentSummaryAr"='صريف الأسنان هو إطباق الأسنان أو حكّها ببعضها، غالبا أثناء الليل ودون وعي. قد يؤدي إلى تآكل الأسنان وآلام في الفك أو صداع. تجمع الرعاية بين تخفيف التوتر وحماية الأسنان ومعالجة الأسباب، تحت إشراف مختص.', "treatmentStepsAr"='تعرّف على العلامات: أسنان متآكلة، فك مؤلم عند الاستيقاظ، صداع أو صوت صرير يلاحظه المحيطون.
استشر طبيب أسنان لتقييم حالة الأسنان ومفصل الفك.
استكشف مع مختص العوامل المساهمة، خصوصا التوتر واضطرابات النوم.
ناقش مع الطبيب وسيلة حماية سنّية مناسبة للحد من التآكل ليلا.
اعتمد تدابير للاسترخاء ومتابعة منتظمة لمراقبة التطور.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['stress', 'mal-de-tete']::text[] WHERE "slug"='bruxisme';
UPDATE "health_topics" SET "treatmentSummary"='Le burn-out est un épuisement profond lié au travail, mêlant fatigue durable, perte de motivation et sentiment d''inefficacité. Il ne se règle pas par un simple repos et nécessite d''être reconnu tôt. La prise en charge associe une mise à distance des facteurs de stress et un accompagnement par un professionnel de santé.', "treatmentSteps"='Reconnaître les signaux d''alerte : fatigue qui persiste malgré le repos, cynisme, difficultés de concentration et perte de sens.
En parler à un professionnel de santé (médecin ou psychologue) pour faire le point et être orienté.
Aménager, quand c''est possible, une mise à distance des facteurs de stress et un temps de récupération.
Mettre en place un accompagnement pour retrouver un équilibre et prévenir la rechute.
Consulter rapidement en cas de détresse importante, d''idées noires ou d''incapacité à fonctionner au quotidien.', "treatmentSummaryAr"='الاحتراق النفسي إرهاق عميق مرتبط بالعمل، يجمع بين تعب مستمر وفقدان الحافز والشعور بعدم الفعالية. لا يُحلّ براحة بسيطة ويجب التعرّف عليه مبكرا. تجمع الرعاية بين الابتعاد عن عوامل التوتر ومواكبة من مختص في الصحة.', "treatmentStepsAr"='تعرّف على علامات الإنذار: تعب يستمر رغم الراحة، سلبية، صعوبة في التركيز وفقدان للمعنى.
تحدّث إلى مختص في الصحة (طبيب أو أخصائي نفسي) لتقييم الوضع والتوجيه.
رتّب، متى أمكن، ابتعادا عن عوامل التوتر ووقتا للتعافي.
اعتمد مواكبة لاستعادة التوازن والوقاية من الانتكاس.
استشر بسرعة في حال ضائقة كبيرة أو أفكار سوداء أو عجز عن أداء المهام اليومية.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['stress', 'anxiete']::text[] WHERE "slug"='burn-out';
UPDATE "health_topics" SET "treatmentSummary"='Les calculs biliaires sans symptôme sont souvent simplement surveillés par un médecin. En cas de douleurs répétées ou de complication, une consultation en gastro-entérologie ou chirurgie oriente vers l''ablation de la vésicule. Une alimentation moins grasse peut limiter les crises. Une douleur intense du ventre à droite, une fièvre ou une jaunisse imposent une consultation en urgence.', "treatmentSteps"='Consulter un médecin en cas de douleurs répétées sous les côtes à droite, souvent après un repas gras.
Confirmer les calculs par une imagerie prescrite (échographie) et évaluer le risque avec le médecin.
Adopter une alimentation moins riche en graisses pour limiter les crises.
Discuter avec un chirurgien de l''ablation de la vésicule si les crises se répètent ou se compliquent.
Consulter en urgence en cas de douleur intense, de fièvre, de vomissements ou de jaunisse.', "treatmentSummaryAr"='غالبًا ما تُراقَب حصى المرارة عديمة الأعراض من طرف الطبيب فقط. عند الآلام المتكرّرة أو حدوث مضاعفة، توجّه استشارة أمراض الجهاز الهضمي أو الجراحة نحو استئصال المرارة. قد تحدّ تغذية أقلّ دسمًا من النوبات. الألم الشديد في أعلى البطن يمينًا أو الحمّى أو اليرقان تفرض استشارة عاجلة.', "treatmentStepsAr"='استشر طبيبًا عند آلام متكرّرة تحت الأضلاع يمينًا، غالبًا بعد وجبة دسمة.
أكّد وجود الحصى بتصوير موصوف (صدى) وقيّم الخطر مع الطبيب.
اعتمد تغذية أقلّ دسمًا للحدّ من النوبات.
ناقش مع الجرّاح استئصال المرارة إن تكرّرت النوبات أو تعقّدت.
استشر بشكل عاجل عند ألم شديد أو حمّى أو تقيّؤ أو يرقان.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['jaunisse', 'mal-de-ventre']::text[] WHERE "slug"='calculs-biliaires';
UPDATE "health_topics" SET "treatmentSummary"='Les calculs rénaux sont de petits cristaux formés dans les reins, qui peuvent provoquer des douleurs intenses (colique néphrétique). Beaucoup s''éliminent naturellement. Un médecin généraliste ou un urologue évalue la situation ; boire suffisamment est essentiel pour prévenir la formation et faciliter l''élimination des calculs.', "treatmentSteps"='Consultez un médecin en cas de douleur du dos ou du flanc, de sang dans les urines ou de brûlures.
Buvez de l''eau en quantité suffisante tout au long de la journée pour aider à éliminer les calculs.
Une imagerie et une analyse peuvent être demandées pour localiser et caractériser le calcul.
Un urologue peut être consulté pour les calculs volumineux ou récidivants.
Consultez en urgence en cas de douleur brutale et intense, de fièvre ou de difficulté à uriner.', "treatmentSummaryAr"='حصى الكلى بلورات صغيرة تتكوّن في الكلى وقد تسبّب آلاماً شديدة (المغص الكلوي). يخرج الكثير منها تلقائياً. يقيّم الطبيب العام أو طبيب المسالك الحالة، وشرب كمية كافية من الماء أساسي للوقاية وتسهيل خروج الحصى.', "treatmentStepsAr"='استشر طبيباً عند ألم الظهر أو الخاصرة أو دم في البول أو حُرقان.
اشرب كمية كافية من الماء طوال اليوم للمساعدة على طرد الحصى.
قد يُطلب تصوير وتحليل لتحديد موقع الحصاة وخصائصها.
يمكن استشارة طبيب مسالك للحصى الكبيرة أو المتكرّرة.
استشر بشكل عاجل عند ألم مفاجئ وشديد أو حمى أو صعوبة في التبوّل.', "preventionSummary"='On peut réduire nettement le risque de calculs rénaux, surtout chez les personnes déjà touchées. Le facteur le plus important est l''hydratation : boire suffisamment dilue les urines et limite la formation de cristaux. L''alimentation joue aussi un rôle. Après un premier calcul, un bilan médical aide à cibler les mesures de prévention les plus utiles.', "preventionSteps"='Boire de l''eau régulièrement pour avoir des urines claires.
Réduire le sel et les excès de protéines animales.
Limiter les boissons sucrées et adapter l''alimentation aux conseils reçus.
Bouger régulièrement et surveiller son poids.
Faire un bilan médical après un premier calcul pour prévenir la récidive.', "preventionSummaryAr"='يمكن خفض خطر حصى الكلى بوضوح، خاصة لدى من سبق أن أصيبوا بها. العامل الأهم هو شرب الماء، إذ يخفّف البول ويحدّ من تكوّن البلورات. كما يلعب النظام الغذائي دورًا. وبعد أول حصاة يساعد الفحص الطبي على تحديد أنسب تدابير الوقاية.', "preventionStepsAr"='شرب الماء بانتظام للحصول على بول صافٍ.
تقليل الملح والإفراط في البروتينات الحيوانية.
الحدّ من المشروبات السكرية وتكييف التغذية مع النصائح المتلقّاة.
الحركة بانتظام ومراقبة الوزن.
إجراء فحص طبي بعد أول حصاة للوقاية من التكرار.', "relatedTopicSlugs"=ARRAY['colique-nephretique', 'brulures-urinaires']::text[] WHERE "slug"='calculs-renaux';
UPDATE "health_topics" SET "treatmentSummary"=NULL, "treatmentSteps"=NULL, "treatmentSummaryAr"=NULL, "treatmentStepsAr"=NULL, "preventionSummary"='On ne prévient pas totalement le cancer colorectal, mais on en réduit le risque par le mode de vie, et surtout on le détecte tôt grâce au dépistage. Le test après 50 ans, ou plus tôt en cas d''antécédents familiaux, permet de repérer des lésions avant qu''elles ne deviennent cancéreuses. Parlez-en à votre médecin.', "preventionSteps"='Réaliser le dépistage recommandé dès 50 ans, ou plus tôt selon vos antécédents familiaux.
Limiter viandes rouges et charcuteries, et augmenter fibres, légumes et fruits.
Réduire l''alcool et arrêter le tabac.
Maintenir un poids sain et une activité physique régulière.
Signaler à votre médecin tout saignement ou changement durable du transit.', "preventionSummaryAr"='لا يمكن الوقاية التامة من سرطان القولون والمستقيم، لكن يمكن خفض خطره بنمط الحياة، والأهم كشفه مبكرًا عبر الفحص. يسمح الاختبار بعد سن الخمسين، أو أبكر عند وجود سوابق عائلية، بكشف آفات قبل أن تصبح سرطانية. تحدّث مع طبيبك حول ذلك.', "preventionStepsAr"='إجراء الفحص الموصى به ابتداءً من سن الخمسين، أو أبكر حسب سوابقك العائلية.
الحد من اللحوم الحمراء واللحوم المصنعة، وزيادة الألياف والخضروات والفواكه.
تقليل الكحول والإقلاع عن التدخين.
الحفاظ على وزن صحي ونشاط بدني منتظم.
إخبار طبيبك بأي نزيف أو تغيّر مستمر في حركة الأمعاء.', "relatedTopicSlugs"=ARRAY[]::text[] WHERE "slug"='cancer-colorectal';
UPDATE "health_topics" SET "treatmentSummary"=NULL, "treatmentSteps"=NULL, "treatmentSummaryAr"=NULL, "treatmentStepsAr"=NULL, "preventionSummary"='Le cancer de la peau ne s''évite pas totalement, mais la protection solaire réduit fortement le risque, et la surveillance des grains de beauté permet de le détecter tôt. Le dépistage repère les mélanomes précocement, quand ils se soignent le mieux. Faites examiner par un dermatologue toute lésion qui change d''aspect.', "preventionSteps"='Éviter l''exposition solaire aux heures les plus chaudes et l''usage des cabines UV.
Se protéger avec vêtements, chapeau, lunettes et crème solaire à indice élevé.
Protéger particulièrement les enfants, dont les coups de soleil comptent double.
Surveiller ses grains de beauté et repérer toute forme, couleur ou taille inhabituelle.
Consulter un dermatologue devant toute lésion nouvelle ou qui évolue.', "preventionSummaryAr"='لا يمكن تجنّب سرطان الجلد تمامًا، لكن الحماية من الشمس تخفض الخطر بقوة، ومراقبة الشامات تسمح بكشفه مبكرًا. يكشف الفحص الأورام الميلانينية باكرًا حين يكون علاجها أنجع. اعرض على طبيب الجلد أي آفة يتغيّر مظهرها.', "preventionStepsAr"='تجنّب التعرض للشمس في أشد ساعات الحر واستعمال أجهزة التسمير.
الحماية بالملابس والقبعة والنظارات وكريم واقٍ بمعامل مرتفع.
حماية الأطفال بشكل خاص، فحروق الشمس لديهم أشد أثرًا.
مراقبة الشامات ورصد أي شكل أو لون أو حجم غير معتاد.
استشارة طبيب الجلد عند أي آفة جديدة أو متطوّرة.', "relatedTopicSlugs"=ARRAY[]::text[] WHERE "slug"='cancer-de-la-peau';
UPDATE "health_topics" SET "treatmentSummary"=NULL, "treatmentSteps"=NULL, "treatmentSummaryAr"=NULL, "treatmentStepsAr"=NULL, "preventionSummary"='Le cancer du sein ne se prévient pas complètement, mais un mode de vie sain réduit le risque, et le dépistage permet de le détecter tôt, quand il se soigne le mieux. La mammographie de dépistage à partir de 40-50 ans et l''auto-surveillance sont essentielles. Votre médecin adapte le suivi à vos antécédents personnels et familiaux.', "preventionSteps"='Participer au dépistage par mammographie selon l''âge et vos antécédents.
Connaître ses seins et consulter devant toute grosseur ou changement.
Limiter l''alcool, dont la consommation augmente le risque.
Maintenir un poids sain et une activité physique régulière, surtout après la ménopause.
Signaler à votre médecin tout antécédent familial pour un suivi personnalisé.', "preventionSummaryAr"='لا يمكن الوقاية الكاملة من سرطان الثدي، لكن نمط الحياة الصحي يخفض الخطر، ويسمح الفحص بكشفه مبكرًا حين يكون العلاج أنجع. يُعدّ تصوير الثدي الإشعاعي ابتداءً من سن 40-50 والمراقبة الذاتية أساسيين. يكيّف طبيبك المتابعة حسب سوابقك الشخصية والعائلية.', "preventionStepsAr"='المشاركة في الفحص بتصوير الثدي الإشعاعي حسب السن والسوابق.
معرفة طبيعة الثديين واستشارة الطبيب عند أي كتلة أو تغيّر.
الحد من الكحول، فاستهلاكه يزيد الخطر.
الحفاظ على وزن صحي ونشاط بدني منتظم، خاصة بعد سن اليأس.
إخبار طبيبك بأي سابقة عائلية من أجل متابعة مخصصة.', "relatedTopicSlugs"=ARRAY[]::text[] WHERE "slug"='cancer-du-sein';
UPDATE "health_topics" SET "treatmentSummary"='Une carence en fer se corrige après avoir identifié sa cause avec un médecin généraliste, sur la base d''un bilan sanguin. Une alimentation riche en fer aide, mais toute supplémentation doit être médicalement encadrée. Chez la femme, des règles abondantes sont une cause fréquente. Une fatigue marquée ou des signes d''anémie justifient une consultation sans attendre.', "treatmentSteps"='Consulter un médecin devant une fatigue, une pâleur, une chute de cheveux ou un essoufflement, et faire doser le fer par une prise de sang.
Rechercher la cause avec le médecin : alimentation, saignements, règles abondantes ou trouble digestif.
Privilégier une alimentation riche en fer selon les conseils du médecin.
Suivre la supplémentation uniquement si elle est prescrite, et respecter les contrôles sanguins.
Reconsulter si la fatigue persiste ou en cas de saignements inexpliqués.', "treatmentSummaryAr"='يُصحَّح نقص الحديد بعد تحديد سببه مع طبيب عام، بناءً على تحليل دم. تساعد التغذية الغنية بالحديد، لكن أي مكمّل يجب أن يكون تحت إشراف طبّي. عند المرأة، تُعدّ الدورة الغزيرة سببًا شائعًا. التعب الواضح أو علامات فقر الدم تبرّر استشارة دون تأخير.', "treatmentStepsAr"='استشر طبيبًا عند تعب أو شحوب أو تساقط شعر أو ضيق تنفّس، وقِس الحديد بتحليل دم.
ابحث عن السبب مع الطبيب: تغذية، نزيف، دورة غزيرة أو اضطراب هضمي.
فضّل تغذية غنية بالحديد وفق نصائح الطبيب.
اتّبع المكمّلات فقط إن كانت موصوفة، والتزم بالتحاليل الدموية.
أعد الاستشارة إذا استمرّ التعب أو عند نزيف غير مبرّر.', "preventionSummary"='La carence en fer se prévient en partie par l''alimentation, mais elle a souvent une cause à identifier (règles abondantes, saignements, grossesse). On ne se supplémente pas au hasard : seul un bilan sanguin confirme le manque. Consultez un médecin devant une fatigue persistante pour en chercher l''origine.', "preventionSteps"='Consommer des sources de fer : viandes, légumineuses, légumes verts, œufs.
Associer les végétaux riches en fer à de la vitamine C pour mieux l''absorber.
Éviter thé et café juste après les repas, qui freinent l''absorption du fer.
Surveiller les femmes ayant des règles abondantes et les femmes enceintes.
Consulter un médecin devant une fatigue persistante plutôt que se supplémenter seul.', "preventionSummaryAr"='يمكن الوقاية جزئيًا من نقص الحديد عبر التغذية، لكن غالبًا ما يكون له سبب يجب تحديده (طمث غزير، نزيف، حمل). لا تُؤخذ المكملات عشوائيًا: تحليل الدم وحده يؤكد النقص. استشر طبيبًا عند تعب مستمر للبحث عن سببه.', "preventionStepsAr"='تناول مصادر الحديد: اللحوم، البقوليات، الخضروات الخضراء، البيض.
دمج النباتات الغنية بالحديد مع فيتامين C لتحسين امتصاصه.
تجنّب الشاي والقهوة بعد الوجبات مباشرة، فهما يعيقان امتصاص الحديد.
مراقبة النساء ذوات الطمث الغزير والحوامل.
استشارة طبيب عند تعب مستمر بدل أخذ المكملات ذاتيًا.', "relatedTopicSlugs"=ARRAY['anemie', 'fatigue']::text[] WHERE "slug"='carence-en-fer';
UPDATE "health_topics" SET "treatmentSummary"='Une carence en vitamine D se confirme par une prise de sang prescrite par un médecin. L''exposition raisonnée au soleil et une alimentation adaptée aident, mais toute supplémentation doit être encadrée pour éviter les excès. Un endocrinologue intervient dans les cas particuliers. Des douleurs osseuses ou une fatigue persistante justifient une consultation, surtout chez les personnes âgées ou peu exposées au soleil.', "treatmentSteps"='Consulter un médecin en cas de fatigue, de douleurs osseuses ou musculaires, ou de facteurs de risque, et faire doser la vitamine D si nécessaire.
S''exposer raisonnablement à la lumière du jour selon les conseils du médecin.
Adopter une alimentation adaptée, sans prendre de compléments de sa propre initiative.
Suivre la supplémentation uniquement si elle est prescrite et respecter les contrôles.
Reconsulter si les symptômes persistent ou s''aggravent.', "treatmentSummaryAr"='يُؤكَّد نقص فيتامين د بتحليل دم يصفه الطبيب. يساعد التعرّض المعقول للشمس وتغذية ملائمة، لكن أي مكمّل يجب أن يكون تحت إشراف لتفادي الإفراط. يتدخّل طبيب الغدد في الحالات الخاصّة. آلام العظام أو التعب المستمر تبرّر استشارة، خصوصًا لدى المسنّين أو قليلي التعرّض للشمس.', "treatmentStepsAr"='استشر طبيبًا عند تعب أو آلام عظمية أو عضلية أو وجود عوامل خطر، وقِس فيتامين د عند اللزوم.
تعرّض بشكل معقول لضوء النهار وفق نصائح الطبيب.
اعتمد تغذية ملائمة، دون تناول مكمّلات من تلقاء نفسك.
اتّبع المكمّلات فقط إن كانت موصوفة والتزم بالفحوص.
أعد الاستشارة إذا استمرّت الأعراض أو تفاقمت.', "preventionSummary"='La carence en vitamine D est fréquente mais largement évitable grâce à une exposition solaire raisonnable et à l''alimentation. Certaines personnes (peu exposées, âgées, peau foncée) restent à risque. Une prise de sang permet de la dépister ; c''est le médecin qui décide d''un dosage et d''une éventuelle correction.', "preventionSteps"='S''exposer raisonnablement au soleil, quelques minutes plusieurs fois par semaine.
Consommer des sources alimentaires : poissons gras, œufs, produits enrichis.
Être vigilant chez les personnes âgées, voilées ou peu exposées au soleil.
Ne pas se supplémenter seul : demander l''avis d''un médecin avant tout complément.
Faire doser la vitamine D uniquement si votre médecin le juge utile.', "preventionSummaryAr"='نقص فيتامين د شائع لكنه قابل للوقاية إلى حد كبير عبر تعرّض معقول للشمس والتغذية. تبقى بعض الفئات معرّضة (قليلو التعرّض، المسنون، أصحاب البشرة الداكنة). يسمح تحليل الدم بكشفه، والطبيب هو من يقرر إجراء القياس والتصحيح عند الاقتضاء.', "preventionStepsAr"='التعرّض للشمس باعتدال، بضع دقائق عدة مرات في الأسبوع.
تناول مصادر غذائية: الأسماك الدهنية، البيض، المنتجات المدعّمة.
الحذر لدى المسنين والمحجبات وقليلي التعرّض للشمس.
عدم أخذ المكملات ذاتيًا: استشارة الطبيب قبل أي مكمّل.
قياس فيتامين د فقط إذا رأى طبيبك ذلك مفيدًا.', "relatedTopicSlugs"=ARRAY['fatigue']::text[] WHERE "slug"='carence-en-vitamine-d';
UPDATE "health_topics" SET "treatmentSummary"='La carie est une destruction progressive de la dent par les bactéries. Une fois installée, elle ne guérit pas seule : seul un chirurgien-dentiste peut nettoyer la zone atteinte et restaurer la dent. Plus on consulte tôt, plus le soin est simple. En prévention, l''hygiène quotidienne et les contrôles réguliers restent essentiels.', "treatmentSteps"='Consulter un chirurgien-dentiste dès l''apparition d''une sensibilité, d''une douleur ou d''une tache sur une dent.
Laisser le praticien examiner la bouche et, si besoin, réaliser une radiographie pour évaluer l''étendue de l''atteinte.
Suivre le soin proposé pour nettoyer la partie abîmée et restaurer la dent afin de préserver sa fonction.
Adopter au quotidien un brossage soigneux et limiter les aliments et boissons sucrés, selon les conseils reçus.
Programmer des contrôles réguliers pour dépister d''éventuelles nouvelles caries à un stade précoce.', "treatmentSummaryAr"='التسوس هو تلف تدريجي للسن تسببه البكتيريا، ولا يشفى من تلقاء نفسه بمجرد ظهوره: وحده طبيب الأسنان يمكنه تنظيف المنطقة المصابة وترميم السن. كلما استشرت مبكرا كان العلاج أبسط. وللوقاية، تبقى النظافة اليومية والفحوص المنتظمة أساسية.', "treatmentStepsAr"='استشر طبيب أسنان فور ظهور حساسية أو ألم أو بقعة على أحد الأسنان.
دع الطبيب يفحص الفم، وإذا لزم الأمر يجري صورة إشعاعية لتقدير مدى الإصابة.
اتبع العلاج المقترح لتنظيف الجزء المتضرر وترميم السن حفاظا على وظيفته.
احرص يوميا على تفريش دقيق للأسنان وقلّل من الأطعمة والمشروبات السكرية وفق النصائح المتلقاة.
احجز فحوصا منتظمة لاكتشاف أي تسوس جديد في مرحلة مبكرة.', "preventionSummary"='La carie dentaire est en grande partie évitable. Elle résulte de l''action des bactéries sur les sucres : limiter le sucre, se brosser les dents au fluor et consulter régulièrement le dentiste réduisent fortement le risque. Le dépistage précoce lors d''un contrôle permet de traiter une carie débutante avant qu''elle ne s''aggrave.', "preventionSteps"='Se brosser les dents deux fois par jour avec un dentifrice fluoré.
Limiter les boissons sucrées et le grignotage sucré entre les repas.
Nettoyer entre les dents avec du fil ou des brossettes.
Consulter un dentiste au moins une fois par an pour un contrôle.
Demander conseil au dentiste sur le fluor pour les enfants.', "preventionSummaryAr"='يمكن تفادي تسوّس الأسنان إلى حد كبير. ينتج عن فعل البكتيريا على السكريات، لذا فإن تقليل السكر وتنظيف الأسنان بمعجون يحتوي على الفلور وزيارة طبيب الأسنان بانتظام تقلّل الخطر بشكل كبير. ويسمح الكشف المبكر أثناء الفحص بعلاج تسوّس مبتدئ قبل أن يتفاقم.', "preventionStepsAr"='تنظيف الأسنان مرتين يوميًا بمعجون يحتوي على الفلور.
الحدّ من المشروبات السكرية والتسالي الحلوة بين الوجبات.
تنظيف ما بين الأسنان بالخيط أو بالفرشاة الصغيرة.
زيارة طبيب الأسنان مرة في السنة على الأقل للفحص.
استشارة طبيب الأسنان حول الفلور بالنسبة للأطفال.', "relatedTopicSlugs"=ARRAY['mal-de-dents', 'abces-dentaire', 'gingivite']::text[] WHERE "slug"='carie-dentaire';
UPDATE "health_topics" SET "treatmentSummary"='La cataracte se soigne par une intervention chirurgicale, seul traitement efficace, décidée avec un ophtalmologue quand la gêne visuelle devient importante. Avant l''opération, un simple ajustement des lunettes peut aider. Le suivi ophtalmologique régulier permet de choisir le bon moment. Une baisse de vision progressive ou un éblouissement gênant justifient une consultation spécialisée sans attendre.', "treatmentSteps"='Consulter un ophtalmologue devant une vision progressivement trouble, un éblouissement ou des couleurs ternies.
Faire évaluer la gêne et le stade de la cataracte lors d''un examen ophtalmologique complet.
Adapter temporairement les lunettes tant que la gêne reste modérée.
Décider avec l''ophtalmologue du moment de l''intervention chirurgicale.
Respecter le suivi post-opératoire et consulter vite en cas de douleur ou de baisse brutale de vision.', "treatmentSummaryAr"='يُعالَج الساد (الماء الأبيض) بعملية جراحية، وهي العلاج الفعّال الوحيد، تُقرَّر مع طبيب العيون عندما يصبح الإزعاج البصري كبيرًا. قبل العملية، قد يساعد تعديل بسيط للنظّارات. تتيح المتابعة المنتظمة اختيار الوقت المناسب. تراجع البصر التدريجي أو الوهج المزعج يبرّران استشارة مختصّة دون تأخير.', "treatmentStepsAr"='استشر طبيب عيون عند ضبابية متزايدة في الرؤية أو وهج أو بهتان في الألوان.
قيّم درجة الإزعاج ومرحلة الساد خلال فحص شامل للعين.
عدّل النظّارات مؤقّتًا ما دام الإزعاج معتدلًا.
قرّر مع طبيب العيون موعد العملية الجراحية.
التزم بالمتابعة بعد العملية واستشر بسرعة عند ألم أو تراجع مفاجئ في البصر.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['astigmatisme']::text[] WHERE "slug"='cataracte';
UPDATE "health_topics" SET "treatmentSummary"='La chute de cheveux peut être passagère (stress, carence, post-partum, saison) ou durable. Un médecin généraliste ou un dermatologue recherche la cause par un examen et parfois un bilan sanguin. Identifier l''origine est essentiel avant tout traitement, car la prise en charge diffère selon qu''elle est réversible ou non.', "treatmentSteps"='Consultez un médecin généraliste ou un dermatologue pour distinguer une chute passagère d''une chute durable.
Signalez les facteurs récents : stress, accouchement, régime, fatigue, maladie ou changement de traitement.
Un bilan sanguin peut être proposé pour rechercher une carence (fer, vitamines) ou un trouble thyroïdien.
Adoptez une alimentation équilibrée et des soins capillaires doux, sans traction ni produits agressifs.
Reconsultez si la chute est rapide, localisée en plaques ou associée à d''autres symptômes.', "treatmentSummaryAr"='قد يكون تساقط الشعر مؤقتاً (توتر، نقص غذائي، ما بعد الولادة، تغيّر الفصول) أو دائماً. يبحث الطبيب العام أو طبيب الجلد عن السبب عبر الفحص وأحياناً تحليل الدم. تحديد الأصل أساسي قبل أي علاج، لأن التدبير يختلف حسب كون التساقط قابلاً للعكس أم لا.', "treatmentStepsAr"='استشر طبيباً عاماً أو طبيب أمراض جلدية للتمييز بين تساقط مؤقت وتساقط دائم.
أبلغ عن العوامل الأخيرة: التوتر، الولادة، الحمية، الإرهاق، المرض أو تغيير الدواء.
قد يُقترح تحليل دم للبحث عن نقص (الحديد، الفيتامينات) أو اضطراب في الغدة الدرقية.
اتبع نظاماً غذائياً متوازناً وعناية لطيفة بالشعر دون شدّ أو منتجات قاسية.
عاود الاستشارة إذا كان التساقط سريعاً أو على شكل بقع أو مصحوباً بأعراض أخرى.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['carence-en-fer', 'hypothyroidie']::text[] WHERE "slug"='chute-de-cheveux';
UPDATE "health_topics" SET "treatmentSummary"='La conjonctivite guérit souvent en quelques jours avec des soins d''hygiène et des mesures simples, sur conseil d''un médecin ou d''un pharmacien. La cause (virale, bactérienne ou allergique) oriente la conduite à tenir. Une bonne hygiène des mains limite la contagion. Une douleur vive, une baisse de vision ou une sensibilité à la lumière imposent une consultation ophtalmologique rapide.', "treatmentSteps"='Reconnaître les signes : œil rouge, larmoiement, sensation de grain de sable ou sécrétions.
Nettoyer l''œil avec des soins d''hygiène simples et se laver soigneusement les mains pour éviter la contagion.
Demander conseil à un pharmacien ou à un médecin pour identifier la cause probable.
Éviter le port de lentilles et le partage de serviettes le temps de la guérison.
Consulter un ophtalmologue en cas de douleur intense, de baisse de vision ou de photophobie.', "treatmentSummaryAr"='غالبًا ما يشفى التهاب الملتحمة خلال أيّام بعناية بالنظافة وتدابير بسيطة، بنصيحة من طبيب أو صيدلي. يوجّه السبب (فيروسي أو جرثومي أو تحسّسي) طريقة التعامل. تحدّ نظافة اليدين الجيّدة من العدوى. الألم الحادّ أو تراجع البصر أو الحساسية للضوء تفرض استشارة عيون سريعة.', "treatmentStepsAr"='تعرّف على العلامات: احمرار العين، دماع، إحساس بحبيبات رمل أو إفرازات.
نظّف العين بعناية بسيطة واغسل يديك جيّدًا لتفادي العدوى.
اطلب نصيحة صيدلي أو طبيب لتحديد السبب المحتمل.
تجنّب العدسات ومشاركة المناشف إلى حين الشفاء.
استشر طبيب عيون عند ألم شديد أو تراجع بصر أو حساسية للضوء.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['allergie']::text[] WHERE "slug"='conjonctivite';
UPDATE "health_topics" SET "treatmentSummary"='La constipation s''améliore le plus souvent en agissant sur le mode de vie : boire suffisamment, augmenter les fibres alimentaires et pratiquer une activité physique régulière. Il est utile de ne pas retenir l''envie d''aller à la selle. Une consultation est recommandée si le trouble s''installe, s''accompagne de douleurs, de sang dans les selles ou d''un changement récent du transit.', "treatmentSteps"='Boire suffisamment d''eau tout au long de la journée
Augmenter progressivement les fibres (fruits, légumes, céréales complètes)
Bouger régulièrement et répondre à l''envie d''aller à la selle
Consulter un médecin si la constipation persiste ou est douloureuse
Consulter rapidement si sang dans les selles ou transit brutalement modifié', "treatmentSummaryAr"='يتحسّن الإمساك غالبًا بالعمل على نمط الحياة: شرب كمية كافية من الماء، زيادة الألياف الغذائية، وممارسة نشاط بدني منتظم. من المفيد عدم كبت الرغبة في التبرّز. تُنصح الاستشارة إذا استقرّ الاضطراب، أو رافقه ألم أو دم في البراز أو تغيّر حديث في العبور المعوي.', "treatmentStepsAr"='شرب كمية كافية من الماء طوال اليوم
زيادة الألياف تدريجيًا (فواكه، خضروات، حبوب كاملة)
الحركة بانتظام والاستجابة للرغبة في التبرّز
استشارة طبيب إذا استمرّ الإمساك أو كان مؤلمًا
استشارة سريعة عند دم في البراز أو تغيّر مفاجئ في العبور المعوي', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-ventre', 'ballonnements', 'syndrome-de-l-intestin-irritable']::text[] WHERE "slug"='constipation';
UPDATE "health_topics" SET "treatmentSummary"=NULL, "treatmentSteps"=NULL, "treatmentSummaryAr"=NULL, "treatmentStepsAr"=NULL, "preventionSummary"='Le coup de soleil est presque toujours évitable en se protégeant du rayonnement ultraviolet. Éviter le soleil aux heures les plus fortes, se couvrir et appliquer une protection solaire suffisent le plus souvent. La prévention est importante car les coups de soleil répétés augmentent le risque de cancer de la peau à long terme.', "preventionSteps"='Éviter l''exposition au soleil entre 11 h et 16 h.
Porter chapeau, lunettes et vêtements couvrants.
Appliquer une crème solaire indice élevé, renouvelée souvent.
Protéger particulièrement les enfants et les nourrissons.
Consulter en cas de brûlure étendue, de cloques ou de malaise.', "preventionSummaryAr"='يمكن تفادي حروق الشمس دائمًا تقريبًا عبر الحماية من الأشعة فوق البنفسجية. وغالبًا ما يكفي تجنّب الشمس في أشدّ ساعاتها والتغطّي ووضع واقٍ من الشمس. والوقاية مهمة لأن حروق الشمس المتكررة تزيد على المدى البعيد من خطر الإصابة بسرطان الجلد.', "preventionStepsAr"='تجنّب التعرّض للشمس ما بين الحادية عشرة صباحًا والرابعة مساءً.
ارتداء قبعة ونظارات وملابس ساترة.
وضع كريم واقٍ من الشمس بمؤشر مرتفع مع تجديده باستمرار.
حماية الأطفال والرضّع بشكل خاص.
الاستشارة عند حرق واسع أو ظهور بثور أو توعّك.', "relatedTopicSlugs"=ARRAY[]::text[] WHERE "slug"='coup-de-soleil';
UPDATE "health_topics" SET "treatmentSummary"=NULL, "treatmentSteps"=NULL, "treatmentSummaryAr"=NULL, "treatmentStepsAr"=NULL, "preventionSummary"='On ne prévient pas la COVID-19 à 100 %, mais on réduit fortement le risque de contamination et de forme grave. La vaccination (surtout pour les personnes fragiles), l''aération des lieux clos et le lavage des mains restent les gestes les plus efficaces. Le port du masque garde son utilité en cas de circulation active du virus.', "preventionSteps"='Se faire vacciner selon les recommandations, surtout si vous êtes âgé, enceinte ou fragile.
Aérer régulièrement les pièces et privilégier les espaces ventilés.
Se laver les mains au savon ou au gel hydroalcoolique.
Porter un masque dans les lieux bondés en période d''épidémie.
Rester chez soi et consulter un médecin en cas de symptômes.', "preventionSummaryAr"='لا يمكن الوقاية من كوفيد-19 بنسبة 100%، لكن يمكن خفض خطر العدوى والأشكال الخطيرة بشكل كبير. يبقى التلقيح (خاصة للأشخاص الهشين) وتهوية الأماكن المغلقة وغسل اليدين أكثر التدابير فعالية. ويحتفظ ارتداء الكمامة بفائدته عند انتشار الفيروس بقوة.', "preventionStepsAr"='أخذ اللقاح حسب التوصيات، خاصة إذا كنت مسنًا أو حاملًا أو من ذوي المناعة الضعيفة.
تهوية الغرف بانتظام وتفضيل الأماكن جيدة التهوية.
غسل اليدين بالصابون أو بالمعقم الكحولي.
ارتداء الكمامة في الأماكن المزدحمة خلال فترات الوباء.
البقاء في المنزل واستشارة الطبيب عند ظهور الأعراض.', "relatedTopicSlugs"=ARRAY[]::text[] WHERE "slug"='covid-19';
UPDATE "health_topics" SET "treatmentSummary"='Les démangeaisons peuvent venir d''une peau sèche, d''une allergie, d''une infection ou d''une cause interne. Si elles persistent, s''étendent ou perturbent le sommeil, un médecin généraliste ou un dermatologue en recherche l''origine. Éviter de gratter et hydrater la peau soulage en attendant la consultation.', "treatmentSteps"='Consultez un médecin si les démangeaisons durent, s''étendent ou empêchent de dormir.
Hydratez la peau avec un émollient doux et évitez les douches trop chaudes et les savons agressifs.
Évitez de gratter, coupez les ongles courts et portez des vêtements amples en coton.
Signalez au médecin tout élément déclenchant : nouveau produit, aliment, médicament ou voyage récent.
Consultez sans tarder en cas de démangeaisons généralisées, de jaunisse associée ou de fièvre.', "treatmentSummaryAr"='قد تنجم الحكة عن جفاف الجلد أو حساسية أو عدوى أو سبب داخلي. إذا استمرت أو اتسعت أو أزعجت النوم، يبحث الطبيب العام أو طبيب الجلد عن أصلها. تجنّب الحك وترطيب البشرة يخففان الأعراض في انتظار الاستشارة.', "treatmentStepsAr"='استشر طبيباً إذا استمرت الحكة أو اتسعت أو منعت النوم.
رطّب البشرة بمرطّب لطيف وتجنّب الاستحمام الساخن جداً والصابون القاسي.
تجنّب الحك، قصّ الأظافر قصيرة، والبس ملابس واسعة من القطن.
أبلغ الطبيب بأي عامل محفّز: منتج جديد، طعام، دواء أو سفر حديث.
استشر دون تأخير عند حكة معمّمة أو مصحوبة باصفرار الجلد أو حمى.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['urticaire', 'eruption-cutanee']::text[] WHERE "slug"='demangeaisons';
UPDATE "health_topics" SET "treatmentSummary"='La dépression est une maladie fréquente qui se soigne, distincte d''une simple baisse de moral passagère. Elle associe tristesse durable, perte d''intérêt et fatigue. Un médecin généraliste ou un psychiatre pose le diagnostic et coordonne la prise en charge. En parler est la première étape essentielle vers le rétablissement.', "treatmentSteps"='Parlez-en à un médecin généraliste ou à un psychiatre dès que les symptômes durent plusieurs semaines.
Un suivi psychologique (psychothérapie) peut être proposé, seul ou associé à un accompagnement médical.
Maintenez autant que possible un rythme de vie régulier : sommeil, activité, liens sociaux.
Appuyez-vous sur l''entourage et respectez les rendez-vous de suivi, sans arrêter la prise en charge seul.
Demandez de l''aide en urgence en cas d''idées noires ou de pensées suicidaires.', "treatmentSummaryAr"='الاكتئاب مرض شائع قابل للعلاج، ويختلف عن مجرد هبوط عابر في المزاج. يجمع بين حزن مستمر وفقدان الاهتمام والإرهاق. يشخّصه الطبيب العام أو الطبيب النفسي وينسّق العلاج. التحدّث عنه هو الخطوة الأولى الأساسية نحو التعافي.', "treatmentStepsAr"='تحدّث مع طبيب عام أو طبيب نفسي بمجرد استمرار الأعراض عدة أسابيع.
قد تُقترح متابعة نفسية (علاج نفسي)، وحدها أو مصحوبة بمرافقة طبية.
حافظ قدر الإمكان على إيقاع حياة منتظم: النوم، النشاط، العلاقات الاجتماعية.
استند إلى المحيطين واحترم مواعيد المتابعة دون إيقاف العلاج بمفردك.
اطلب المساعدة بشكل عاجل عند وجود أفكار سوداء أو أفكار انتحارية.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['burn-out', 'anxiete']::text[] WHERE "slug"='depression';
UPDATE "health_topics" SET "treatmentSummary"='Le diabète se gère au long cours avec un médecin traitant : équilibre alimentaire, activité physique régulière, suivi du poids et surveillance de la glycémie. Un endocrinologue intervient pour les cas complexes ou déséquilibrés. Le but est d''éviter les complications (yeux, reins, cœur, pieds) par un contrôle durable, un dépistage régulier et une bonne éducation thérapeutique.', "treatmentSteps"='Consulter un médecin généraliste devant une soif intense, des envies fréquentes d''uriner ou une fatigue persistante, et faire confirmer le diagnostic par une prise de sang.
Mettre en place une hygiène de vie adaptée : alimentation équilibrée, réduction des sucres rapides, activité physique régulière et suivi du poids.
Apprendre à surveiller sa glycémie et respecter le suivi médical prescrit, sans jamais modifier soi-même son traitement.
Réaliser les dépistages réguliers des complications : fond d''œil, reins, pieds, bilan cardiovasculaire.
Consulter en urgence en cas de malaise, de confusion, de vomissements ou de glycémie très anormale.', "treatmentSummaryAr"='يُدار مرض السكري على المدى الطويل مع طبيب معالج: توازن غذائي، نشاط بدني منتظم، مراقبة الوزن ومتابعة نسبة السكر في الدم. يتدخّل طبيب الغدد في الحالات المعقّدة أو غير المتوازنة. الهدف هو تفادي المضاعفات (العينان، الكليتان، القلب، القدمان) عبر ضبط دائم وفحص منتظم وتربية علاجية جيّدة.', "treatmentStepsAr"='استشر طبيبًا عامًّا عند العطش الشديد أو كثرة التبوّل أو التعب المستمر، وأكّد التشخيص بتحليل دم.
اعتمد نمط حياة ملائمًا: تغذية متوازنة، تقليل السكريات السريعة، نشاط بدني منتظم ومتابعة الوزن.
تعلّم مراقبة نسبة السكر في دمك والتزم بالمتابعة الطبية الموصوفة، دون تغيير علاجك بنفسك أبدًا.
أجرِ الفحوص المنتظمة للمضاعفات: قاع العين، الكليتان، القدمان، تقييم القلب والأوعية.
استشر بشكل عاجل عند الإغماء أو التشوّش أو التقيّؤ أو ارتفاع أو انخفاض حادّ في السكر.', "preventionSummary"='Le diabète de type 2 est en grande partie évitable en agissant sur le mode de vie : poids, alimentation et activité physique. Le type 1 ne se prévient pas. Le dépistage régulier de la glycémie, surtout en cas d''antécédents familiaux ou de surpoids, permet une prise en charge précoce. Un médecin évalue vos facteurs de risque personnels.', "preventionSteps"='Maintenir un poids sain et réduire le tour de taille, principal facteur de risque modifiable.
Privilégier une alimentation riche en fibres, légumes et céréales complètes, en limitant sucres rapides et boissons sucrées.
Pratiquer au moins 150 minutes d''activité physique modérée par semaine (marche, natation, vélo).
Arrêter le tabac et limiter l''alcool, qui aggravent le risque métabolique.
Faire contrôler sa glycémie régulièrement en cas de surpoids ou d''antécédents familiaux.', "preventionSummaryAr"='يمكن الوقاية إلى حد كبير من السكري من النوع الثاني عبر التحكم في الوزن والتغذية والنشاط البدني، أما النوع الأول فلا يمكن الوقاية منه. يساعد الفحص المنتظم لسكر الدم، خاصة عند وجود سوابق عائلية أو زيادة في الوزن، على التكفل المبكر. يقيّم الطبيب عوامل الخطر الخاصة بك.', "preventionStepsAr"='الحفاظ على وزن صحي وتقليص محيط الخصر، وهو أهم عامل خطر قابل للتعديل.
تفضيل تغذية غنية بالألياف والخضروات والحبوب الكاملة، مع الحد من السكريات السريعة والمشروبات المحلاة.
ممارسة 150 دقيقة على الأقل من النشاط البدني المعتدل أسبوعيًا (المشي، السباحة، الدراجة).
الإقلاع عن التدخين والحد من الكحول، لأنهما يفاقمان الخطر الأيضي.
مراقبة سكر الدم بانتظام عند وجود زيادة في الوزن أو سوابق عائلية.', "relatedTopicSlugs"=ARRAY['obesite', 'hypercholesterolemie']::text[] WHERE "slug"='diabete';
UPDATE "health_topics" SET "treatmentSummary"='La diarrhée aiguë est souvent d''origine virale ou alimentaire et cède en quelques jours. La priorité est la réhydratation régulière par petites quantités, avec une alimentation légère. Une hygiène des mains rigoureuse limite la contagion. Une consultation s''impose chez le nourrisson ou la personne âgée, ou en cas de fièvre élevée, de sang dans les selles ou de signes de déshydratation.', "treatmentSteps"='Se réhydrater régulièrement par petites quantités
Privilégier une alimentation légère et éviter les aliments gras
Se laver les mains soigneusement pour éviter la transmission
Surveiller la déshydratation, surtout aux âges fragiles
Consulter si fièvre élevée, sang dans les selles ou diarrhée prolongée', "treatmentSummaryAr"='الإسهال الحاد غالبًا فيروسي أو غذائي المنشأ ويزول في غضون أيام. الأولوية للترطيب المنتظم بكميات صغيرة مع أكل خفيف. نظافة اليدين الدقيقة تحدّ من العدوى. تلزم الاستشارة عند الرضيع أو المسنّ، أو عند حمى مرتفعة أو دم في البراز أو علامات جفاف.', "treatmentStepsAr"='الترطيب المنتظم بكميات صغيرة
تفضيل أكل خفيف وتجنّب الأطعمة الدهنية
غسل اليدين جيدًا لتفادي انتقال العدوى
مراقبة الجفاف، خاصة في الأعمار الهشّة
الاستشارة عند حمى مرتفعة أو دم في البراز أو إسهال مطوّل', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['gastro-enterite', 'mal-de-ventre', 'nausees-et-vomissements']::text[] WHERE "slug"='diarrhee';
UPDATE "health_topics" SET "treatmentSummary"='Les douleurs articulaires peuvent avoir de nombreuses causes : usure, inflammation, effort ou maladie générale. Un médecin généraliste fait le point et oriente vers un rhumatologue si besoin. Bouger en douceur, éviter la surcharge et surveiller les signes inflammatoires aident à orienter la prise en charge.', "treatmentSteps"='Consultez un médecin généraliste pour rechercher la cause et évaluer les articulations concernées.
Notez le contexte : douleur au repos ou à l''effort, raideur matinale, gonflement, rougeur ou fièvre.
Maintenez une activité douce adaptée et évitez les mouvements qui aggravent la douleur.
Un bilan ou un avis rhumatologique peut être proposé si plusieurs articulations sont touchées.
Consultez rapidement en cas d''articulation chaude, gonflée et très douloureuse, surtout avec de la fièvre.', "treatmentSummaryAr"='قد تكون لآلام المفاصل أسباب عديدة: تآكل، التهاب، مجهود أو مرض عام. يقيّم الطبيب العام الحالة ويوجّه إلى طبيب روماتيزم عند الحاجة. الحركة اللطيفة وتجنّب الإفراط ومراقبة العلامات الالتهابية تساعد على توجيه العلاج.', "treatmentStepsAr"='استشر طبيباً عاماً للبحث عن السبب وتقييم المفاصل المعنية.
لاحظ السياق: ألم عند الراحة أو المجهود، تيبّس صباحي، تورّم، احمرار أو حمى.
حافظ على نشاط لطيف مناسب وتجنّب الحركات التي تزيد الألم.
قد يُقترح فحص أو استشارة طبيب روماتيزم إذا أُصيبت عدة مفاصل.
استشر بسرعة عند مفصل ساخن ومتورّم وشديد الألم، خاصة مع الحمى.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['arthrose', 'polyarthrite-rhumatoide']::text[] WHERE "slug"='douleurs-articulaires';
UPDATE "health_topics" SET "treatmentSummary"='L''eczéma se contrôle en hydratant quotidiennement la peau, en évitant les irritants et les facteurs déclenchants, et avec les soins prescrits lors des poussées. Il ne se « guérit » pas en une fois mais se stabilise bien avec un suivi. Le dermatologue adapte le traitement et recherche d''éventuelles allergies.', "treatmentSteps"='Hydrater la peau tous les jours avec un émollient adapté.
Identifier et éviter les irritants et facteurs déclenchants.
Consulter un médecin pour les poussées et suivre les soins prescrits.
Dermatologue ou allergologue si les poussées sont fréquentes ou étendues.', "treatmentSummaryAr"='يُضبَط الإكزيما بترطيب البشرة يومياً، تجنّب المُهيّجات والعوامل المُحفِّزة، والعناية الموصوفة أثناء الهجمات. لا «يُشفى» دفعةً واحدة لكنّه يستقرّ جيداً مع المتابعة. يُكيّف طبيب الجلد العلاج ويبحث عن حساسية محتملة.', "treatmentStepsAr"='ترطيب البشرة يومياً بمُرطّب مناسب.
تحديد وتجنّب المُهيّجات والعوامل المُحفِّزة.
استشارة طبيب أثناء الهجمات والالتزام بالعناية الموصوفة.
طبيب الجلد أو الحساسية إذا كانت الهجمات متكرّرة أو واسعة.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['demangeaisons', 'acne', 'allergie']::text[] WHERE "slug"='eczema';
UPDATE "health_topics" SET "treatmentSummary"='La gastrite se soulage d''abord en agissant sur sa cause : arrêt du tabac et de l''alcool, repas plus légers et gestion du stress. Une consultation permet de rechercher une bactérie ou un facteur irritant. Le médecin peut proposer un traitement adapté et, si besoin, des examens. Une prise en charge est urgente en cas de douleur intense ou de sang dans les vomissements.', "treatmentSteps"='Consulter un médecin pour identifier la cause de la gastrite
Adapter l''alimentation et limiter tabac, alcool et aliments irritants
Suivre le traitement et les examens proposés si nécessaire
Gérer le stress, souvent aggravant
Consulter en urgence si douleur intense ou sang dans les vomissements', "treatmentSummaryAr"='يُخفَّف التهاب المعدة أولًا بالعمل على سببه: الإقلاع عن التدخين والكحول، وجبات أخف، وإدارة التوتر. تسمح الاستشارة بالبحث عن بكتيريا أو عامل مُهيّج. قد يقترح الطبيب علاجًا مناسبًا وفحوصًا عند الحاجة. تصبح الرعاية عاجلة عند ألم شديد أو دم في القيء.', "treatmentStepsAr"='استشارة طبيب لتحديد سبب التهاب المعدة
تكييف الأكل والحدّ من التدخين والكحول والأطعمة المُهيّجة
اتباع العلاج والفحوص المقترحة عند الضرورة
إدارة التوتر الذي غالبًا ما يُفاقم الحالة
استشارة عاجلة عند ألم شديد أو دم في القيء', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-ventre', 'reflux-gastro-oesophagien', 'ulcere-gastrique']::text[] WHERE "slug"='gastrite';
UPDATE "health_topics" SET "treatmentSummary"='La gastro-entérite est une infection digestive le plus souvent virale qui guérit en quelques jours. La priorité est de compenser les pertes en eau par une réhydratation régulière, en petites quantités. Une alimentation légère est reprise progressivement. Une consultation est nécessaire chez le nourrisson, la personne âgée, ou en cas de signes de déshydratation ou de sang dans les selles.', "treatmentSteps"='Se réhydrater régulièrement par petites gorgées
Reprendre une alimentation légère dès que possible
Se laver soigneusement les mains pour limiter la contagion
Surveiller les signes de déshydratation, surtout aux âges fragiles
Consulter si vomissements persistants, sang dans les selles ou déshydratation', "treatmentSummaryAr"='التهاب المعدة والأمعاء عدوى هضمية غالبًا فيروسية تُشفى في غضون أيام. الأولوية تعويض فقدان الماء بترطيب منتظم بكميات صغيرة. يُستأنف الأكل الخفيف تدريجيًا. تلزم الاستشارة عند الرضيع أو المسنّ، أو عند علامات الجفاف أو وجود دم في البراز.', "treatmentStepsAr"='الترطيب المنتظم برشفات صغيرة
استئناف أكل خفيف في أقرب وقت ممكن
غسل اليدين جيدًا للحدّ من العدوى
مراقبة علامات الجفاف، خاصة في الأعمار الهشّة
الاستشارة عند قيء مستمر أو دم في البراز أو جفاف', "preventionSummary"='La gastro-entérite se prévient bien par l''hygiène, car elle se transmet par les mains, l''eau et les aliments contaminés. Le lavage des mains est le geste clé. Chez le nourrisson, un vaccin contre le rotavirus existe. Bien conserver et cuire les aliments limite aussi le risque. En cas de diarrhée, la priorité est d''éviter la déshydratation.', "preventionSteps"='Se laver les mains avant de cuisiner, de manger et après les toilettes.
Consommer une eau potable et bien laver fruits et légumes.
Respecter la chaîne du froid et bien cuire les aliments sensibles.
Éviter le contact rapproché avec une personne malade.
Consulter en cas de diarrhée sévère, surtout chez l''enfant et la personne âgée.', "preventionSummaryAr"='يمكن الوقاية من التهاب المعدة والأمعاء جيدًا عبر النظافة، لأنه ينتقل عبر اليدين والماء والأطعمة الملوّثة. غسل اليدين هو الإجراء الأساسي. ويوجد لدى الرضّع لقاح ضد فيروس الروتا. كما يحدّ حفظ الأطعمة وطهيها جيدًا من الخطر. وعند الإسهال تكون الأولوية لتفادي الجفاف.', "preventionStepsAr"='غسل اليدين قبل الطبخ والأكل وبعد استعمال المرحاض.
استهلاك ماء صالح للشرب وغسل الفواكه والخضروات جيدًا.
احترام سلسلة التبريد وطهي الأطعمة الحسّاسة جيدًا.
تجنّب الاحتكاك القريب بشخص مريض.
الاستشارة عند إسهال شديد، خاصة لدى الطفل والمسنّ.', "relatedTopicSlugs"=ARRAY['diarrhee', 'nausees-et-vomissements', 'mal-de-ventre']::text[] WHERE "slug"='gastro-enterite';
UPDATE "health_topics" SET "treatmentSummary"='La gingivite est une inflammation des gencives, souvent due à l''accumulation de plaque dentaire ; elles deviennent rouges, gonflées et saignent facilement. Prise tôt, elle est réversible grâce à une bonne hygiène et à un détartrage. Sans soin, elle peut évoluer vers une atteinte plus profonde des tissus de soutien de la dent.', "treatmentSteps"='Repérer les signes : gencives rouges, gonflées ou qui saignent lors du brossage.
Consulter un chirurgien-dentiste pour un examen et, si besoin, un nettoyage professionnel des dents.
Améliorer l''hygiène quotidienne avec un brossage soigneux et un nettoyage entre les dents.
Limiter les facteurs aggravants, notamment le tabac, selon les conseils reçus.
Assurer des contrôles réguliers pour éviter la récidive et une évolution vers une atteinte plus grave.', "treatmentSummaryAr"='التهاب اللثة تهيّج يصيب اللثة، غالبا بسبب تراكم البلاك السني؛ فتصبح حمراء ومتورمة وتنزف بسهولة. إذا عولج مبكرا كان قابلا للتراجع بفضل نظافة جيدة وإزالة الجير. ودون علاج قد يتطور إلى إصابة أعمق في الأنسجة الداعمة للسن.', "treatmentStepsAr"='تعرّف على العلامات: لثة حمراء أو متورمة أو تنزف عند التفريش.
استشر طبيب أسنان للفحص وإجراء تنظيف احترافي للأسنان عند الحاجة.
حسّن النظافة اليومية بتفريش دقيق وتنظيف ما بين الأسنان.
قلّل العوامل المفاقمة، خصوصا التبغ، وفق النصائح المتلقاة.
احرص على فحوص منتظمة لتفادي الانتكاس والتطور نحو إصابة أخطر.', "preventionSummary"='La gingivite est très largement évitable et réversible à un stade précoce. Elle est due à l''accumulation de plaque dentaire le long des gencives. Un brossage soigneux, le nettoyage entre les dents et un détartrage régulier chez le dentiste suffisent souvent à la prévenir. Traitée tôt, elle n''évolue pas vers une atteinte plus grave des gencives.', "preventionSteps"='Se brosser les dents et les gencives matin et soir sans agressivité.
Nettoyer chaque jour entre les dents avec du fil ou une brossette.
Faire réaliser un détartrage régulier chez le dentiste.
Éviter le tabac, qui fragilise les gencives.
Consulter si les gencives saignent ou restent gonflées.', "preventionSummaryAr"='يمكن تفادي التهاب اللثة إلى حد كبير وهو قابل للتراجع في مرحلة مبكرة. يعود سببه إلى تراكم اللويحة الجرثومية على طول اللثة. وغالبًا ما يكفي التنظيف الجيّد وتنظيف ما بين الأسنان وإزالة الجير بانتظام عند طبيب الأسنان للوقاية منه. وإذا عولج مبكرًا لا يتطور نحو إصابة أخطر للثة.', "preventionStepsAr"='تنظيف الأسنان واللثة صباحًا ومساءً دون عنف.
تنظيف ما بين الأسنان يوميًا بالخيط أو بالفرشاة الصغيرة.
إجراء إزالة الجير بانتظام عند طبيب الأسنان.
تجنّب التدخين الذي يُضعف اللثة.
الاستشارة إذا نزفت اللثة أو بقيت منتفخة.', "relatedTopicSlugs"=ARRAY['mauvaise-haleine', 'carie-dentaire']::text[] WHERE "slug"='gingivite';
UPDATE "health_topics" SET "treatmentSummary"='La grippe guérit le plus souvent seule en quelques jours : repos, hydratation et surveillance des symptômes suffisent dans les formes simples. Le médecin peut soulager la fièvre et les courbatures. Les personnes fragiles (âgées, femmes enceintes, maladies chroniques) doivent consulter, et la vaccination reste la meilleure prévention.', "treatmentSteps"='Se reposer, bien s''hydrater et surveiller l''évolution.
Soulager fièvre et courbatures selon l''avis du médecin.
Limiter la contagion (masque, lavage des mains).
Consulter rapidement si personne fragile, essoufflement ou aggravation.
Penser à la vaccination annuelle en prévention.', "treatmentSummaryAr"='تُشفى الإنفلونزا غالباً وحدها خلال أيام: الراحة، شرب السوائل ومراقبة الأعراض تكفي في الأشكال البسيطة. يمكن للطبيب تخفيف الحُمّى وآلام العضلات. على الأشخاص الهشّين (المسنّون، الحوامل، الأمراض المزمنة) الاستشارة، ويبقى التلقيح أفضل وقاية.', "treatmentStepsAr"='الراحة، شرب السوائل بكثرة ومراقبة التطوّر.
تخفيف الحُمّى وآلام العضلات حسب رأي الطبيب.
الحدّ من العدوى (الكمامة، غسل اليدين).
الاستشارة بسرعة عند شخص هشّ أو ضيق تنفّس أو تدهور.
التفكير في التلقيح السنوي للوقاية.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['fievre', 'toux', 'covid-19']::text[] WHERE "slug"='grippe';
UPDATE "health_topics" SET "treatmentSummary"='Les hémorroïdes se soulagent d''abord par des mesures simples : lutter contre la constipation (fibres, hydratation), une bonne hygiène et des soins locaux sur avis médical. En cas de douleur ou de saignement, il faut consulter pour confirmer l''origine. Un gastro-entérologue ou un proctologue propose un geste si les symptômes persistent.', "treatmentSteps"='Lutter contre la constipation : fibres, eau, activité physique.
Soins locaux et hygiène adaptée, sur conseil médical.
Consulter pour tout saignement afin d''en confirmer l''origine.
Proctologue ou gastro-entérologue pour un traitement instrumental si besoin.', "treatmentSummaryAr"='تُخفَّف البواسير أولاً بتدابير بسيطة: مكافحة الإمساك (الألياف، شرب الماء)، نظافة جيدة وعناية موضعية بنصيحة طبية. عند الألم أو النزيف يجب الاستشارة لتأكيد المصدر. يقترح طبيب الجهاز الهضمي أو طبيب المستقيم إجراءً إذا استمرّت الأعراض.', "treatmentStepsAr"='مكافحة الإمساك: ألياف، ماء، نشاط بدني.
عناية موضعية ونظافة مناسبة، بنصيحة طبية.
الاستشارة عند أيّ نزيف لتأكيد مصدره.
طبيب المستقيم أو الجهاز الهضمي لعلاج أداتي عند الحاجة.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['constipation', 'sang-dans-les-selles', 'mal-de-ventre']::text[] WHERE "slug"='hemorroides';
UPDATE "health_topics" SET "treatmentSummary"='Un cholestérol élevé se corrige d''abord par l''alimentation et l''activité physique, sous le suivi d''un médecin généraliste. Un bilan sanguin évalue le risque cardiovasculaire global. Le cardiologue intervient pour les situations à haut risque. L''objectif est de protéger le cœur et les artères durablement, sans jamais s''automédiquer, grâce à un suivi régulier et à des habitudes de vie adaptées.', "treatmentSteps"='Faire un bilan lipidique sur prescription du médecin généraliste, surtout en cas d''antécédents familiaux ou de facteurs de risque.
Adopter une alimentation pauvre en graisses saturées, riche en fibres, et pratiquer une activité physique régulière.
Réduire les facteurs aggravants : tabac, excès de poids, sédentarité et consommation d''alcool.
Respecter le suivi et les contrôles sanguins prescrits pour ajuster la prise en charge avec le médecin.
Consulter sans tarder en cas de douleur thoracique, d''essoufflement inhabituel ou de malaise.', "treatmentSummaryAr"='يُصحَّح ارتفاع الكوليسترول أولًا عبر التغذية والنشاط البدني، تحت متابعة طبيب عام. يقيّم تحليل الدم الخطر القلبي الوعائي الإجمالي. يتدخّل طبيب القلب في الحالات عالية الخطورة. الهدف حماية القلب والشرايين بشكل دائم، دون تداوٍ ذاتي، بفضل متابعة منتظمة وعادات حياة ملائمة.', "treatmentStepsAr"='أجرِ تحليلًا للدهون بوصفة من الطبيب العام، خصوصًا عند وجود سوابق عائلية أو عوامل خطر.
اعتمد تغذية قليلة الدهون المشبعة وغنية بالألياف، ومارس نشاطًا بدنيًّا منتظمًا.
قلّل العوامل المفاقمة: التدخين، زيادة الوزن، قلّة الحركة وتناول الكحول.
التزم بالمتابعة وتحاليل الدم الموصوفة لضبط التدبير مع الطبيب.
استشر دون تأخير عند ألم في الصدر أو ضيق تنفّس غير معتاد أو إغماء.', "preventionSummary"='Un excès de cholestérol est largement modifiable par l''alimentation, l''activité physique et l''arrêt du tabac, même si l''hérédité joue parfois un rôle. Sans symptôme, il se dépiste uniquement par une prise de sang. Un médecin interprète vos résultats et évalue votre risque cardiovasculaire global.', "preventionSteps"='Limiter les graisses saturées (charcuterie, beurre, fritures) au profit d''huiles végétales et de poisson.
Augmenter les fibres : légumes, fruits, légumineuses et céréales complètes.
Pratiquer une activité physique régulière et maintenir un poids sain.
Arrêter le tabac, qui abaisse le bon cholestérol.
Faire un bilan lipidique selon les recommandations de votre médecin.', "preventionSummaryAr"='يمكن تعديل ارتفاع الكوليسترول إلى حد كبير عبر التغذية والنشاط البدني والإقلاع عن التدخين، وإن كان للوراثة دور أحيانًا. وهو بلا أعراض، ولا يُكشف إلا بتحليل الدم. يفسّر الطبيب نتائجك ويقيّم خطرك القلبي الوعائي الإجمالي.', "preventionStepsAr"='الحد من الدهون المشبعة (اللحوم المصنعة، الزبدة، المقليات) لصالح الزيوت النباتية والسمك.
زيادة الألياف: الخضروات والفواكه والبقوليات والحبوب الكاملة.
ممارسة نشاط بدني منتظم والحفاظ على وزن صحي.
الإقلاع عن التدخين الذي يخفض الكوليسترول الجيد.
إجراء تحليل للدهون حسب توصيات طبيبك.', "relatedTopicSlugs"=ARRAY['angine-de-poitrine', 'obesite', 'diabete']::text[] WHERE "slug"='hypercholesterolemie';
UPDATE "health_topics" SET "treatmentSummary"='L''hypertension se prend en charge dans la durée en associant des mesures d''hygiène de vie (alimentation moins salée, activité physique, arrêt du tabac, gestion du stress) et, souvent, un traitement prescrit et suivi par le médecin. Un contrôle régulier de la tension et des examens permettent d''ajuster la prise en charge.', "treatmentSteps"='Confirmer le diagnostic par plusieurs mesures de la tension chez le médecin.
Adopter une alimentation moins salée, une activité physique régulière, arrêter le tabac.
Suivre le traitement prescrit sans jamais l''arrêter de soi-même.
Surveiller sa tension et faire les examens de suivi demandés.
Cardiologue ou néphrologue pour les formes compliquées ou résistantes.', "treatmentSummaryAr"='يُدبَّر ارتفاع ضغط الدم على المدى الطويل بالجمع بين تدابير نمط الحياة (تقليل الملح، النشاط البدني، الإقلاع عن التدخين، إدارة التوتّر) وغالباً علاجٍ يصفه الطبيب ويتابعه. تسمح المراقبة المنتظمة للضغط والفحوص بتعديل التكفّل.', "treatmentStepsAr"='تأكيد التشخيص بعدّة قياسات للضغط عند الطبيب.
اعتماد غذاء أقلّ ملحاً، نشاط بدني منتظم، والإقلاع عن التدخين.
الالتزام بالعلاج الموصوف دون إيقافه ذاتياً أبداً.
مراقبة الضغط وإجراء فحوص المتابعة المطلوبة.
طبيب القلب أو الكلى للأشكال المُعقّدة أو المقاوِمة.', "preventionSummary"='L''hypertension artérielle est souvent évitable ou retardée en agissant sur le sel, le poids et l''activité physique. Silencieuse, elle ne provoque pas de symptômes : seule une mesure régulière de la tension permet de la dépister tôt. Un médecin évalue vos facteurs de risque et vous conseille un suivi adapté.', "preventionSteps"='Réduire la consommation de sel et limiter les plats préparés, conserves et fromages salés.
Maintenir un poids sain et pratiquer une activité physique régulière.
Limiter l''alcool et arrêter le tabac.
Gérer le stress et privilégier un sommeil de qualité.
Faire mesurer sa tension régulièrement, car l''hypertension ne donne aucun signe d''alerte.', "preventionSummaryAr"='غالبًا ما يمكن الوقاية من ارتفاع ضغط الدم أو تأخيره عبر التحكم في الملح والوزن والنشاط البدني. وهو مرض صامت لا يسبب أعراضًا، لذا فإن القياس المنتظم للضغط وحده يسمح بكشفه مبكرًا. يقيّم الطبيب عوامل الخطر لديك وينصحك بمتابعة ملائمة.', "preventionStepsAr"='تقليل استهلاك الملح والحد من الأطباق الجاهزة والمعلبات والأجبان المالحة.
الحفاظ على وزن صحي وممارسة نشاط بدني منتظم.
الحد من الكحول والإقلاع عن التدخين.
إدارة التوتر وتفضيل نوم ذي جودة جيدة.
قياس الضغط بانتظام، لأن ارتفاعه لا يعطي أي إشارة تحذير.', "relatedTopicSlugs"=ARRAY['hypercholesterolemie', 'diabete', 'angine-de-poitrine']::text[] WHERE "slug"='hypertension-arterielle';
UPDATE "health_topics" SET "treatmentSummary"='L''insomnie est une difficulté à s''endormir ou à maintenir le sommeil, avec un retentissement en journée. Occasionnelle, elle est banale ; persistante, elle mérite un avis médical. Un médecin généraliste recherche la cause. L''amélioration de l''hygiène du sommeil est la première approche, avant toute autre solution.', "treatmentSteps"='Consultez un médecin généraliste si l''insomnie dure plusieurs semaines ou retentit sur la journée.
Adoptez des horaires de coucher réguliers et un rituel apaisant avant de dormir.
Limitez les écrans, la caféine et les repas lourds en soirée, et réservez le lit au sommeil.
Recherchez une cause associée : stress, douleur, anxiété ou trouble de l''humeur, à signaler au médecin.
Reconsultez si le sommeil ne s''améliore pas ou si vous ressentez une somnolence marquée dans la journée.', "treatmentSummaryAr"='الأرق صعوبة في النوم أو الحفاظ عليه مع تأثير خلال النهار. عندما يكون عابراً فهو أمر عادي، أما إذا استمر فيستحق استشارة طبية. يبحث الطبيب العام عن السبب. تحسين عادات النوم هو النهج الأول قبل أي حل آخر.', "treatmentStepsAr"='استشر طبيباً عاماً إذا استمر الأرق عدة أسابيع أو أثّر على نهارك.
اعتمد مواعيد نوم منتظمة وطقساً مهدّئاً قبل النوم.
قلّل الشاشات والكافيين والوجبات الثقيلة مساءً، واحصر السرير للنوم.
ابحث عن سبب مصاحب: توتر، ألم، قلق أو اضطراب مزاجي، وأبلغ به الطبيب.
عاود الاستشارة إذا لم يتحسّن النوم أو شعرت بنعاس واضح خلال النهار.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['anxiete', 'depression']::text[] WHERE "slug"='insomnie';
UPDATE "health_topics" SET "treatmentSummary"='La laryngite est le plus souvent virale et régresse en quelques jours. Le repos de la voix, une bonne hydratation, l''humidification de l''air et l''arrêt du tabac aident à la récupération. Il faut éviter de forcer sur la voix. Une consultation s''impose si l''extinction de voix se prolonge, ou en cas de gêne respiratoire, surtout chez l''enfant.', "treatmentSteps"='Mettre la voix au repos et éviter de chuchoter en forçant
S''hydrater, humidifier l''air et éviter tabac et fumée
Soulager la gêne selon les conseils d''un professionnel
Consulter si la voix ne revient pas après une à deux semaines
Consulter en urgence en cas de gêne respiratoire, surtout chez l''enfant', "treatmentSummaryAr"='التهاب الحنجرة غالبًا فيروسي ويتراجع في غضون أيام. راحة الصوت وشرب السوائل وترطيب الهواء والإقلاع عن التدخين تساعد على التعافي. يجب تجنّب إجهاد الصوت. تلزم الاستشارة إذا طال فقدان الصوت، أو عند ضيق التنفّس، خاصة عند الطفل.', "treatmentStepsAr"='إراحة الصوت وتجنّب الهمس بإجهاد
شرب السوائل وترطيب الهواء وتجنّب التدخين والدخان
تخفيف الانزعاج حسب نصيحة مختصّ
الاستشارة إذا لم يعُد الصوت بعد أسبوع إلى أسبوعين
استشارة عاجلة عند ضيق التنفّس، خاصة عند الطفل', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['extinction-de-voix', 'mal-de-gorge', 'angine']::text[] WHERE "slug"='laryngite';
UPDATE "health_topics" SET "treatmentSummary"='La plupart des maux de dos communs s''améliorent en quelques semaines en restant actif, en évitant le repos strict au lit et avec la kinésithérapie. Le médecin généraliste évalue la douleur et oriente si besoin. Si elle persiste, descend dans la jambe ou s''accompagne de signes d''alerte, un rhumatologue approfondit.', "treatmentSteps"='Rester actif : le repos strict au lit prolongé est déconseillé.
Consulter un médecin généraliste si la douleur gêne le quotidien ou dure.
Kinésithérapie et exercices adaptés, sur conseil médical.
Rhumatologue en cas de douleur persistante, inflammatoire ou irradiante.
Consulter en urgence en cas de perte de force, de troubles urinaires ou de fièvre.', "treatmentSummaryAr"='معظم آلام الظهر الشائعة تتحسّن خلال أسابيع مع البقاء نشيطاً، تجنّب الراحة التامّة في الفراش، والعلاج الطبيعي. يقيّم الطبيب العام الألم ويوجّه عند الحاجة. إذا استمرّ أو نزل إلى الساق أو رافقته علامات إنذار، يتعمّق طبيب الروماتيزم.', "treatmentStepsAr"='ابقَ نشيطاً: يُنصَح بتجنّب الراحة التامّة الطويلة في الفراش.
استشر طبيباً عاماً إذا أعاق الألم حياتك اليومية أو طال.
علاج طبيعي وتمارين مُكيّفة، بنصيحة طبية.
طبيب الروماتيزم عند ألم مستمرّ أو التهابي أو مُمتدّ.
استشر بشكل عاجل عند فقدان القوّة أو اضطرابات بولية أو حُمّى.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['sciatique', 'douleurs-articulaires', 'arthrose']::text[] WHERE "slug"='mal-de-dos';
UPDATE "health_topics" SET "treatmentSummary"='La migraine se traite à deux niveaux : soulager la crise dès les premiers signes, et, si les crises sont fréquentes, un traitement de fond prescrit par le médecin. Le repos au calme, l''hydratation et l''identification des facteurs déclenchants aident. Un neurologue ou un médecin généraliste adapte la prise en charge à votre cas.', "treatmentSteps"='Consultez un médecin généraliste pour confirmer qu''il s''agit bien de migraines et écarter une autre cause.
Notez vos crises (fréquence, durée, déclencheurs) dans un agenda pour aider le diagnostic.
Traitement de la crise : agir tôt, se reposer au calme, selon la prescription du médecin.
Si les crises sont fréquentes ou invalidantes, le médecin peut proposer un traitement de fond.
Un neurologue intervient pour les formes résistantes ou atypiques.', "treatmentSummaryAr"='يُعالَج الصداع النصفي على مستويين: تخفيف النوبة عند أوّل علاماتها، وعند تكرّرها علاجٌ وقائيّ يصفه الطبيب. تساعد الراحة في مكان هادئ، شرب الماء وتحديد العوامل المُحفِّزة. يُكيّف طبيب الأعصاب أو الطبيب العام التكفّل حسب حالتك.', "treatmentStepsAr"='استشر طبيباً عاماً لتأكيد أنّها نوبات صداع نصفي واستبعاد سبب آخر.
دوّن نوباتك (التكرار، المدّة، المُحفِّزات) في مفكّرة لمساعدة التشخيص.
علاج النوبة: التدخّل مبكراً والراحة في مكان هادئ، حسب وصفة الطبيب.
عند تكرّر النوبات أو إعاقتها لحياتك، قد يقترح الطبيب علاجاً وقائياً.
يتدخّل طبيب الأعصاب في الأشكال المقاوِمة أو غير النمطية.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-tete', 'vertiges', 'anxiete']::text[] WHERE "slug"='migraine';
UPDATE "health_topics" SET "treatmentSummary"='Une mycose cutanée est une infection de la peau due à des champignons, favorisée par la chaleur et l''humidité. Elle se traite bien mais peut récidiver. Un médecin généraliste ou un dermatologue confirme l''origine des lésions, car d''autres affections leur ressemblent, et oriente vers la prise en charge adaptée.', "treatmentSteps"='Consultez un médecin généraliste ou un dermatologue pour confirmer qu''il s''agit bien d''une mycose et non d''une autre affection cutanée.
Gardez les zones atteintes propres et sèches : séchez bien les plis, changez de linge régulièrement.
Évitez de partager serviettes, chaussures et vêtements pour ne pas transmettre l''infection.
Suivez la durée de prise en charge indiquée par le médecin, même après disparition des symptômes, pour éviter la rechute.
Reconsultez si les lésions s''étendent, ne s''améliorent pas ou reviennent souvent, notamment en cas de diabète.', "treatmentSummaryAr"='الفطريات الجلدية عدوى تصيب الجلد بسبب الفطريات، وتزيد الحرارة والرطوبة من ظهورها. تُعالَج جيداً لكنها قد تتكرر. يؤكد الطبيب العام أو طبيب الجلد أصل الآفات لأن أمراضاً أخرى قد تشبهها، ويوجّه نحو العلاج المناسب.', "treatmentStepsAr"='استشر طبيباً عاماً أو طبيب أمراض جلدية للتأكد من أنها فطريات وليست مرضاً جلدياً آخر.
حافظ على المناطق المصابة نظيفة وجافة: جفّف الثنايا جيداً وغيّر الملابس بانتظام.
تجنّب مشاركة المناشف والأحذية والملابس لتفادي نقل العدوى.
التزم بمدة العلاج التي يحددها الطبيب حتى بعد اختفاء الأعراض لتجنّب الانتكاس.
عاود الاستشارة إذا اتسعت الآفات أو لم تتحسن أو تكررت كثيراً، خاصة عند مرضى السكري.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['pied-d-athlete', 'demangeaisons']::text[] WHERE "slug"='mycose-cutanee';
UPDATE "health_topics" SET "treatmentSummary"='L''obésité se prend en charge sur la durée avec un médecin généraliste, autour d''une alimentation équilibrée, d''une activité physique progressive et d''un accompagnement psychologique si besoin. Un nutritionniste ou un endocrinologue peut compléter le suivi. L''objectif est une perte de poids réaliste et durable, jamais des régimes extrêmes. Un dépistage des complications (diabète, cœur, articulations) fait partie du parcours.', "treatmentSteps"='Consulter un médecin généraliste pour un bilan complet et identifier les causes et facteurs associés.
Fixer des objectifs réalistes et adopter une alimentation équilibrée et une activité physique progressive.
Se faire accompagner si besoin par un nutritionniste, un psychologue ou un endocrinologue.
Dépister et surveiller les complications éventuelles : diabète, tension, cholestérol, articulations.
Maintenir un suivi régulier pour ancrer les changements dans la durée et éviter les régimes dangereux.', "treatmentSummaryAr"='تُدار السمنة على المدى الطويل مع طبيب عام، حول تغذية متوازنة ونشاط بدني تدريجي ومرافقة نفسية عند الحاجة. قد يكمّل المتابعةَ اختصاصيُّ تغذية أو طبيب غدد. الهدف فقدان وزن واقعي ودائم، لا حميات قاسية. ويشمل المسار فحص المضاعفات (السكري، القلب، المفاصل).', "treatmentStepsAr"='استشر طبيبًا عامًّا لإجراء تقييم شامل وتحديد الأسباب والعوامل المرتبطة.
حدّد أهدافًا واقعية واعتمد تغذية متوازنة ونشاطًا بدنيًّا تدريجيًّا.
استعن عند الحاجة باختصاصي تغذية أو أخصّائي نفسي أو طبيب غدد.
افحص وراقب المضاعفات المحتملة: السكري، الضغط، الكوليسترول، المفاصل.
حافظ على متابعة منتظمة لترسيخ التغييرات على المدى البعيد وتفادي الحميات الخطيرة.', "preventionSummary"='L''obésité résulte de facteurs multiples (alimentation, activité, sommeil, hérédité, environnement) et se prévient surtout par des habitudes durables plutôt que par des régimes stricts. Agir tôt limite les complications comme le diabète. Un médecin ou un nutritionniste vous aide à fixer des objectifs réalistes et personnalisés.', "preventionSteps"='Adopter une alimentation équilibrée et régulière, en limitant produits ultra-transformés et boissons sucrées.
Bouger chaque jour et réduire le temps passé assis.
Veiller à un sommeil suffisant, dont le manque favorise la prise de poids.
Repérer les grignotages liés au stress ou aux émotions.
Se faire accompagner par un professionnel plutôt que multiplier les régimes restrictifs.', "preventionSummaryAr"='تنتج السمنة عن عوامل متعددة (التغذية، النشاط، النوم، الوراثة، المحيط)، والوقاية منها تكون بعادات مستدامة أكثر من الحميات الصارمة. التدخل المبكر يحد من مضاعفات مثل السكري. يساعدك الطبيب أو أخصائي التغذية على تحديد أهداف واقعية ومخصصة.', "preventionStepsAr"='اعتماد تغذية متوازنة ومنتظمة، مع الحد من المنتجات فائقة التصنيع والمشروبات المحلاة.
الحركة يوميًا وتقليل الوقت المقضي جالسًا.
الحرص على نوم كافٍ، لأن نقصه يشجّع على زيادة الوزن.
الانتباه إلى القضم المرتبط بالتوتر أو المشاعر.
الاستعانة بمختص بدل تكرار الحميات التقييدية.', "relatedTopicSlugs"=ARRAY['diabete', 'hypercholesterolemie', 'apnee-du-sommeil']::text[] WHERE "slug"='obesite';
UPDATE "health_topics" SET "treatmentSummary"=NULL, "treatmentSteps"=NULL, "treatmentSummaryAr"=NULL, "treatmentStepsAr"=NULL, "preventionSummary"='On peut fortement limiter l''ostéoporose en construisant un capital osseux solide dès le jeune âge et en le préservant ensuite par l''alimentation, l''activité physique et l''arrêt du tabac. Après la ménopause, une ostéodensitométrie peut la dépister. Un médecin évalue votre risque de fracture et vous conseille.', "preventionSteps"='Assurer des apports suffisants en calcium (produits laitiers, eaux riches, légumes verts).
Maintenir un bon taux de vitamine D, avec une exposition solaire raisonnable.
Pratiquer une activité physique en charge : marche, montée d''escaliers, renforcement.
Arrêter le tabac et limiter l''alcool et l''excès de café.
Discuter d''un dépistage par ostéodensitométrie après la ménopause avec votre médecin.', "preventionSummaryAr"='يمكن الحد بقوة من هشاشة العظام ببناء رصيد عظمي متين منذ الصغر ثم الحفاظ عليه عبر التغذية والنشاط البدني والإقلاع عن التدخين. بعد سن اليأس، يمكن لقياس كثافة العظام كشفها. يقيّم الطبيب خطر الكسر لديك وينصحك.', "preventionStepsAr"='ضمان مدخول كافٍ من الكالسيوم (منتجات الألبان، المياه الغنية، الخضروات الخضراء).
الحفاظ على مستوى جيد من فيتامين د، مع تعرّض معقول للشمس.
ممارسة نشاط بدني حامل للوزن: المشي، صعود الدرج، تقوية العضلات.
الإقلاع عن التدخين والحد من الكحول والإفراط في القهوة.
مناقشة فحص كثافة العظام بعد سن اليأس مع طبيبك.', "relatedTopicSlugs"=ARRAY[]::text[] WHERE "slug"='osteoporose';
UPDATE "health_topics" SET "treatmentSummary"='L''otite nécessite un examen du tympan par un médecin, car la prise en charge dépend du type d''otite. La douleur peut être soulagée selon la prescription. Certaines otites guérissent seules, d''autres justifient un traitement. Un ORL intervient pour les otites à répétition ou compliquées, surtout chez l''enfant.', "treatmentSteps"='Consulter un médecin pour examiner le tympan et préciser le type d''otite.
Soulager la douleur selon la prescription.
Suivre le traitement éventuel et les consignes de surveillance.
ORL en cas d''otites répétées, de baisse d''audition ou de complications.', "treatmentSummaryAr"='يستلزم التهاب الأذن فحصَ طبلة الأذن عند طبيب، لأنّ التكفّل يعتمد على نوع الالتهاب. يمكن تخفيف الألم حسب الوصفة. بعض الالتهابات تُشفى وحدها وأخرى تستوجب علاجاً. يتدخّل طبيب الأنف والأذن والحنجرة عند الالتهابات المتكرّرة أو المُعقّدة، خاصّةً عند الطفل.', "treatmentStepsAr"='استشارة طبيب لفحص طبلة الأذن وتحديد نوع الالتهاب.
تخفيف الألم حسب الوصفة.
الالتزام بالعلاج المحتمل وتعليمات المراقبة.
طبيب الأنف والأذن والحنجرة عند التهابات متكرّرة أو ضعف سمع أو مضاعفات.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['mal-de-gorge', 'angine', 'acouphenes']::text[] WHERE "slug"='otite';
UPDATE "health_topics" SET "treatmentSummary"='Le psoriasis est une maladie de peau chronique qui évolue par poussées et ne se guérit pas définitivement, mais se contrôle bien. Le suivi repose sur un dermatologue, qui adapte la prise en charge selon l''étendue des plaques. Une bonne hydratation de la peau, l''arrêt du tabac et la gestion du stress limitent les poussées.', "treatmentSteps"='Consultez un médecin généraliste ou directement un dermatologue pour confirmer le diagnostic et évaluer l''étendue des plaques.
Adoptez une routine douce : hydratation quotidienne de la peau, savons surgras, éviter de gratter et de décaper les lésions.
Identifiez et réduisez les facteurs déclenchants : stress, tabac, alcool, certaines infections et frottements répétés.
Suivez le plan de traitement défini par le dermatologue et respectez les rendez-vous de contrôle réguliers.
Reconsultez rapidement en cas de poussée étendue, d''atteinte des articulations ou de retentissement psychologique.', "treatmentSummaryAr"='الصدفية مرض جلدي مزمن يتطور على شكل نوبات ولا يُشفى نهائياً، لكن يمكن التحكم فيه جيداً. تعتمد المتابعة على طبيب الأمراض الجلدية الذي يكيّف العلاج حسب اتساع البقع. يساعد ترطيب البشرة الجيد والإقلاع عن التدخين والتحكم في التوتر على الحد من النوبات.', "treatmentStepsAr"='استشر طبيباً عاماً أو طبيب أمراض جلدية مباشرة لتأكيد التشخيص وتقييم اتساع البقع.
اتبع روتيناً لطيفاً: ترطيب يومي للبشرة، استعمال صابون مرطّب، وتجنّب الحك ونزع القشور.
حدّد العوامل المحفّزة وقلّل منها: التوتر، التدخين، الكحول، بعض العدوى والاحتكاك المتكرر.
التزم بخطة العلاج التي يحددها طبيب الجلد واحترم مواعيد المراقبة المنتظمة.
عاود الاستشارة بسرعة عند نوبة واسعة أو إصابة المفاصل أو تأثير نفسي كبير.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['demangeaisons', 'eruption-cutanee']::text[] WHERE "slug"='psoriasis';
UPDATE "health_topics" SET "treatmentSummary"='Le reflux gastro-œsophagien s''améliore souvent grâce à des mesures d''hygiène de vie : repas plus légers, éviter de se coucher juste après avoir mangé, réduire le tabac, l''alcool et l''excès de poids. Une consultation permet d''évaluer la gêne et de proposer une prise en charge adaptée. Des signes comme une difficulté à avaler ou un amaigrissement imposent un avis médical.', "treatmentSteps"='Adapter les repas et éviter de s''allonger juste après manger
Réduire tabac, alcool, aliments déclenchants et excès de poids
Surélever la tête du lit si les symptômes sont nocturnes
Consulter un médecin si la gêne est fréquente ou persistante
Consulter sans tarder en cas de difficulté à avaler ou d''amaigrissement', "treatmentSummaryAr"='يتحسّن الارتجاع المعدي المريئي غالبًا بفضل تدابير نمط الحياة: وجبات أخف، تجنّب الاستلقاء مباشرة بعد الأكل، تقليل التدخين والكحول وزيادة الوزن. تسمح الاستشارة بتقييم الانزعاج واقتراح علاج مناسب. علامات مثل صعوبة البلع أو نقص الوزن تستوجب رأيًا طبيًا.', "treatmentStepsAr"='تكييف الوجبات وتجنّب الاستلقاء مباشرة بعد الأكل
تقليل التدخين والكحول والأطعمة المُحفّزة وزيادة الوزن
رفع رأس السرير إذا كانت الأعراض ليلية
استشارة طبيب إذا كان الانزعاج متكررًا أو مستمرًا
استشارة سريعة عند صعوبة البلع أو نقص الوزن', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['gastrite', 'hernie-hiatale', 'mal-de-ventre']::text[] WHERE "slug"='reflux-gastro-oesophagien';
UPDATE "health_topics" SET "treatmentSummary"='La rhinite allergique se gère avant tout en réduisant l''exposition à l''allergène en cause. Une consultation permet d''identifier le déclencheur et d''orienter, si besoin, vers un allergologue. Le médecin peut proposer une prise en charge de fond pour espacer les crises. L''objectif est d''améliorer le confort quotidien et de prévenir l''évolution vers de l''asthme.', "treatmentSteps"='Repérer et limiter le contact avec l''allergène suspecté
Consulter un médecin pour confirmer l''origine allergique
Se faire orienter vers un allergologue pour un bilan si nécessaire
Mettre en place la prise en charge de fond proposée
Reconsulter si gêne respiratoire ou toux persistante s''installe', "treatmentSummaryAr"='يُدار التهاب الأنف التحسسي أولًا بتقليل التعرّض لمُسبّب الحساسية. تساعد الاستشارة على تحديد المُحفّز والتوجيه نحو أخصائي حساسية عند الحاجة. قد يقترح الطبيب علاجًا أساسيًا للمباعدة بين النوبات. الهدف تحسين الراحة اليومية والوقاية من التطوّر إلى ربو.', "treatmentStepsAr"='تحديد مُسبّب الحساسية المشتبه به والحدّ من التعرّض له
استشارة طبيب لتأكيد الأصل التحسسي
التوجّه إلى أخصائي حساسية لإجراء فحص عند الضرورة
تطبيق العلاج الأساسي المقترح
إعادة الاستشارة عند ظهور ضيق تنفّس أو سعال مستمر', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['nez-bouche', 'asthme', 'sinusite']::text[] WHERE "slug"='rhinite-allergique';
UPDATE "health_topics" SET "treatmentSummary"='Le rhume est une infection virale bénigne qui guérit seule en quelques jours. La prise en charge repose sur le repos, une bonne hydratation et le lavage du nez au sérum physiologique. Aucun traitement ne raccourcit la durée du virus. Une consultation devient utile si la fièvre est élevée, si les signes se prolongent ou si la respiration devient difficile.', "treatmentSteps"='Se reposer et bien s''hydrater dès les premiers signes
Laver régulièrement le nez au sérum physiologique
Soulager la gêne selon les conseils du pharmacien ou du médecin
Éviter de fumer et aérer les pièces
Consulter si fièvre élevée, gêne respiratoire ou signes durant plus d''une semaine', "treatmentSummaryAr"='الزكام عدوى فيروسية خفيفة تُشفى وحدها في غضون أيام. تعتمد الرعاية على الراحة وشرب السوائل بكثرة وغسل الأنف بالمصل الفسيولوجي. لا يوجد علاج يُقصّر مدة الفيروس. تصبح الاستشارة مفيدة عند ارتفاع الحمى أو استمرار العلامات أو صعوبة التنفس.', "treatmentStepsAr"='الراحة وشرب السوائل بكثرة منذ أول العلامات
غسل الأنف بانتظام بالمصل الفسيولوجي
تخفيف الانزعاج حسب نصيحة الصيدلي أو الطبيب
تجنّب التدخين وتهوية الغرف
الاستشارة عند حمى مرتفعة أو ضيق تنفّس أو علامات تدوم أكثر من أسبوع', "preventionSummary"='Le rhume ne s''évite pas complètement, car de nombreux virus le provoquent et circulent facilement. On peut toutefois réduire nettement le risque de l''attraper ou de le transmettre par des gestes simples d''hygiène. Il n''existe pas de vaccin contre le rhume ; la meilleure défense reste l''hygiène des mains et l''aération des espaces clos.', "preventionSteps"='Se laver les mains fréquemment, surtout en période de rhumes.
Éviter de se toucher le nez, la bouche et les yeux avec des mains sales.
Aérer régulièrement son logement et son lieu de travail.
Tousser et éternuer dans le coude ou un mouchoir jetable.
Consulter un médecin si les symptômes durent ou s''aggravent.', "preventionSummaryAr"='لا يمكن تجنّب الزكام تمامًا لأن فيروسات عديدة تسبّبه وتنتشر بسهولة. غير أنه يمكن خفض خطر الإصابة أو نقل العدوى بشكل واضح عبر إجراءات نظافة بسيطة. لا يوجد لقاح ضد الزكام، وتبقى أفضل حماية هي نظافة اليدين وتهوية الأماكن المغلقة.', "preventionStepsAr"='غسل اليدين بشكل متكرر، خاصة في فترات انتشار الزكام.
تجنّب لمس الأنف والفم والعينين بأيدٍ غير نظيفة.
تهوية المنزل ومكان العمل بانتظام.
السعال والعطس في المرفق أو في منديل يُرمى بعد الاستعمال.
استشارة الطبيب إذا استمرت الأعراض أو تفاقمت.', "relatedTopicSlugs"=ARRAY['nez-bouche', 'mal-de-gorge', 'toux']::text[] WHERE "slug"='rhume';
UPDATE "health_topics" SET "treatmentSummary"='La sciatique est une douleur qui part du bas du dos et descend dans la jambe, souvent liée à un nerf comprimé. Elle guérit le plus souvent en quelques semaines. Un médecin généraliste évalue la situation ; rester actif dans la mesure du possible favorise la récupération plutôt que le repos strict.', "treatmentSteps"='Consultez un médecin généraliste pour confirmer l''origine de la douleur et écarter les signes de gravité.
Restez actif autant que possible et évitez l''alitement prolongé, qui ralentit la récupération.
Adaptez les gestes du quotidien : évitez le port de charges lourdes et les mouvements qui aggravent la douleur.
La kinésithérapie peut être proposée pour soulager et prévenir les récidives.
Consultez en urgence en cas de perte de force dans la jambe, de troubles urinaires ou d''insensibilité entre les cuisses.', "treatmentSummaryAr"='عرق النسا ألم ينطلق من أسفل الظهر وينزل إلى الساق، غالباً بسبب ضغط على عصب. يتحسّن في معظم الحالات خلال بضعة أسابيع. يقيّم الطبيب العام الوضع، والبقاء نشيطاً قدر الإمكان يساعد على التعافي أكثر من الراحة المطلقة.', "treatmentStepsAr"='استشر طبيباً عاماً لتأكيد أصل الألم واستبعاد علامات الخطورة.
ابقَ نشيطاً قدر الإمكان وتجنّب الاستلقاء المطوّل الذي يبطئ التعافي.
كيّف حركاتك اليومية: تجنّب حمل الأثقال والحركات التي تزيد الألم.
قد يُقترح العلاج الطبيعي للتخفيف والوقاية من التكرار.
استشر بشكل عاجل عند فقدان القوة في الساق أو اضطرابات بولية أو فقدان الإحساس بين الفخذين.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['hernie-discale', 'douleurs-articulaires']::text[] WHERE "slug"='sciatique';
UPDATE "health_topics" SET "treatmentSummary"='La sinusite est le plus souvent d''origine virale et guérit spontanément en quelques jours. Le lavage nasal au sérum physiologique, une bonne hydratation et le repos soulagent les symptômes. Une consultation est utile si la douleur du visage est intense, si les signes durent au-delà de dix jours ou s''aggravent, afin que le médecin adapte la prise en charge.', "treatmentSteps"='Soulager les symptômes par lavage nasal, hydratation et repos
Consulter un médecin si les signes durent plus de dix jours ou s''aggravent
Laisser le médecin rechercher une éventuelle surinfection
Suivre la prise en charge proposée, orientée vers un ORL si besoin
Consulter rapidement si fièvre élevée, gonflement ou douleur autour de l''œil', "treatmentSummaryAr"='التهاب الجيوب الأنفية غالبًا فيروسي ويُشفى تلقائيًا في غضون أيام. يخفّف غسل الأنف بالمصل الفسيولوجي وشرب السوائل والراحة الأعراض. تُنصح الاستشارة إذا كان ألم الوجه شديدًا أو استمرّت العلامات أكثر من عشرة أيام أو تفاقمت، ليُكيّف الطبيب طريقة العلاج.', "treatmentStepsAr"='تخفيف الأعراض بغسل الأنف وشرب السوائل والراحة
استشارة الطبيب إذا استمرّت العلامات أكثر من عشرة أيام أو تفاقمت
ترك الطبيب يبحث عن عدوى ثانوية محتملة
اتباع العلاج المقترح مع التوجيه نحو أخصائي أنف وأذن وحنجرة عند الحاجة
استشارة سريعة عند حمى مرتفعة أو انتفاخ أو ألم حول العين', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['nez-bouche', 'rhinite-allergique', 'rhume']::text[] WHERE "slug"='sinusite';
UPDATE "health_topics" SET "treatmentSummary"='La tendinite est une inflammation d''un tendon, souvent due à des gestes répétés ou à une sollicitation excessive. Elle guérit généralement avec du repos et une reprise progressive. Un médecin généraliste évalue l''articulation ; identifier et corriger le geste en cause est la clé pour éviter les récidives.', "treatmentSteps"='Consultez un médecin généraliste pour confirmer la tendinite et localiser le tendon atteint.
Mettez le tendon au repos relatif : réduisez temporairement l''activité ou le geste responsable.
Reprenez progressivement l''activité en corrigeant les gestes ou le matériel en cause.
La kinésithérapie peut être proposée pour rééduquer et renforcer le tendon.
Reconsultez si la douleur persiste plusieurs semaines, réapparaît ou limite fortement le mouvement.', "treatmentSummaryAr"='التهاب الوتر تهيّج يصيب أحد الأوتار، غالباً بسبب حركات متكررة أو إجهاد مفرط. يتحسّن عادةً بالراحة والعودة التدريجية للنشاط. يقيّم الطبيب العام المفصل، وتحديد الحركة المسبّبة وتصحيحها هو مفتاح تفادي التكرار.', "treatmentStepsAr"='استشر طبيباً عاماً لتأكيد التهاب الوتر وتحديد الوتر المصاب.
أرِح الوتر نسبياً: قلّل مؤقتاً من النشاط أو الحركة المسبّبة.
استأنف النشاط تدريجياً مع تصحيح الحركات أو المعدات المسبّبة.
قد يُقترح العلاج الطبيعي لإعادة التأهيل وتقوية الوتر.
عاود الاستشارة إذا استمر الألم أسابيع أو عاد أو حدّ من الحركة بشكل كبير.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['tennis-elbow', 'douleur-a-l-epaule']::text[] WHERE "slug"='tendinite';
UPDATE "health_topics" SET "treatmentSummary"='L''urticaire se manifeste par des plaques rouges en relief qui démangent, apparaissant puis disparaissant sur la peau. Elle est le plus souvent bénigne et passagère. La prise en charge cherche à en identifier le déclencheur et à soulager les démangeaisons ; un gonflement du visage ou une gêne respiratoire imposent une consultation urgente.', "treatmentSteps"='Noter le moment d''apparition et les facteurs possibles (aliment, contact, chaleur, infection récente).
Éviter, quand c''est possible, le déclencheur suspecté et les frottements sur les zones atteintes.
Consulter un médecin si les poussées se répètent, durent ou gênent le quotidien.
Suivre les conseils du professionnel pour apaiser les démangeaisons et surveiller l''évolution.
Appeler les secours en urgence en cas de gonflement des lèvres ou du visage, ou de difficulté à respirer.', "treatmentSummaryAr"='الشرى يظهر على شكل بقع حمراء بارزة مثيرة للحكة، تظهر ثم تختفي على الجلد. وهو غالبا حميد وعابر. تسعى الرعاية إلى تحديد المحفّز وتخفيف الحكة؛ أما تورّم الوجه أو ضيق التنفس فيفرضان استشارة عاجلة.', "treatmentStepsAr"='دوّن وقت الظهور والعوامل المحتملة (طعام، ملامسة، حرارة، عدوى حديثة).
تجنّب متى أمكن المحفّز المشتبه به واحتكاك المناطق المصابة.
استشر طبيبا إذا تكررت النوبات أو استمرت أو أعاقت حياتك اليومية.
اتبع نصائح المختص لتهدئة الحكة ومراقبة التطور.
اتصل بالإسعاف بشكل عاجل في حال تورم الشفتين أو الوجه أو صعوبة التنفس.', "preventionSummary"=NULL, "preventionSteps"=NULL, "preventionSummaryAr"=NULL, "preventionStepsAr"=NULL, "relatedTopicSlugs"=ARRAY['demangeaisons', 'allergie', 'allergie-alimentaire']::text[] WHERE "slug"='urticaire';

-- 36 guides de spécialité (relus = publiés)
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_allergologie', s."id", 'Consultez un allergologue pour des réactions allergiques répétées ou mal identifiées : rhinite saisonnière, urticaire, eczéma, allergie alimentaire suspectée, asthme d''origine allergique ou réactions à des médicaments. L''allergologue recherche les déclencheurs, réalise des tests adaptés et propose un plan pour éviter les allergènes et mieux vivre au quotidien.', 'Éternuements, nez qui coule et yeux qui piquent, surtout par saison
Urticaire ou démangeaisons répétées sans cause évidente
Réaction suspectée après un aliment, une piqûre ou un médicament
Asthme déclenché par la poussière, les pollens ou les animaux
Eczéma persistant ou qui s''aggrave à certaines périodes
Besoin d''identifier précisément un allergène par des tests', 'Gonflement des lèvres, de la langue ou de la gorge après un contact
Difficulté à respirer ou sifflements brutaux après une exposition
Malaise avec chute de tension juste après un aliment, une piqûre ou un médicament', 'Hors urgence, prenez rendez-vous quand des symptômes allergiques reviennent chaque année, gênent votre quotidien, ou quand vous suspectez un aliment ou un produit sans en être sûr. Votre médecin généraliste soulage les épisodes courants et vous adresse à l''allergologue pour des tests, une allergie sévère ou récidivante à identifier précisément.', '[{"q":"Comment sait-on à quoi on est allergique ?","a":"L''allergologue s''appuie sur votre récit (circonstances, saison, aliments) puis réalise des tests cutanés ou sanguins adaptés. Ces examens aident à identifier les déclencheurs et à bâtir un plan d''éviction. Notez à l''avance les situations qui déclenchent vos symptômes."},{"q":"Une allergie alimentaire nécessite-t-elle toujours un bilan ?","a":"Une réaction claire et sévère après un aliment justifie un avis spécialisé sans tarder. Pour des symptômes plus flous, l''allergologue confirme ou écarte l''allergie par des tests, afin d''éviter des exclusions alimentaires inutiles et de sécuriser votre alimentation."}]', NULL, ARRAY['allergie', 'allergie-alimentaire', 'rhinite-allergique', 'asthme']::text[], 'استشر طبيب الحساسية عند تفاعلات تحسّسية متكررة أو غير محدّدة: التهاب أنف موسمي، شرى، إكزيما، اشتباه في حساسية غذائية، ربو تحسّسي أو تفاعلات لأدوية. يبحث الطبيب عن المثيرات، ويجري فحوصًا مناسبة، ويقترح خطة لتجنّب المواد المسبّبة وتحسين الحياة اليومية.', 'عطس وسيلان أنف وحكة في العينين، خاصة حسب الفصل
شرى أو حكة متكررة دون سبب واضح
اشتباه في تفاعل بعد طعام أو لسعة أو دواء
ربو تثيره الغبار أو حبوب اللقاح أو الحيوانات
إكزيما مستمرة أو تتفاقم في فترات معينة
الحاجة إلى تحديد المادة المسبّبة بدقة عبر فحوص', 'انتفاخ الشفتين أو اللسان أو الحلق بعد تماس
صعوبة مفاجئة في التنفس أو صفير بعد تعرّض
إغماء مع هبوط ضغط مباشرة بعد طعام أو لسعة أو دواء', 'خارج الحالات الطارئة، احجز موعدًا حين تتكرر الأعراض التحسّسية كل سنة، أو تعكّر حياتك، أو حين تشتبه في طعام أو منتج دون يقين. يخفّف طبيبك العام النوبات الشائعة ويحوّلك إلى طبيب الحساسية لإجراء فحوص، أو لتحديد حساسية شديدة أو متكررة بدقة.', '[{"q":"كيف نعرف مصدر الحساسية؟","a":"يعتمد طبيب الحساسية على روايتك (الظروف، الفصل، الأطعمة) ثم يجري فحوصًا جلدية أو دموية مناسبة. تساعد هذه الفحوص على تحديد المثيرات وبناء خطة تجنّب. ودوّن مسبقًا الحالات التي تثير أعراضك."},{"q":"هل تستلزم الحساسية الغذائية دائمًا فحصًا؟","a":"التفاعل الواضح والشديد بعد طعام يستوجب رأيًا متخصصًا دون تأخير. أما الأعراض الغامضة، فيؤكّد طبيب الحساسية أو ينفي الحساسية عبر فحوص، لتجنّب استبعاد أطعمة دون داعٍ وتأمين تغذيتك."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='allergologie'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_angiologie', s."id", 'Consultez un angiologue pour les troubles des veines et des artères : varices, jambes lourdes ou gonflées, sensation de froid ou de fourmillements aux extrémités, ou suspicion de phlébite. Spécialiste de la circulation, il examine vos vaisseaux, souvent par échographie Doppler, pour prévenir et prendre en charge les maladies vasculaires.', 'Varices ou veines apparentes gênantes ou douloureuses
Jambes lourdes, gonflées ou douloureuses en fin de journée
Sensation de froid, doigts qui blanchissent (maladie de Raynaud)
Suivi de la circulation en cas de diabète ou de tabagisme
Difficulté à marcher avec douleur des mollets à l''effort
Suivi après une phlébite ou un traitement vasculaire', 'Mollet chaud, rouge, gonflé et douloureux d''un seul côté
Douleur brutale et froideur d''un membre
Plaie du pied qui ne cicatrise pas, surtout chez le diabétique', 'Prenez rendez-vous avec un angiologue quand des varices deviennent gênantes, quand vos jambes sont régulièrement lourdes ou gonflées, ou pour surveiller votre circulation si vous êtes diabétique, fumeur ou à risque vasculaire. Un bilan par échographie Doppler permet d''agir tôt. En cas de mollet brutalement chaud, rouge et douloureux, ou d''un membre froid et douloureux, consultez en urgence : il peut s''agir d''une phlébite ou d''une occlusion.', '[{"q":"Qu''est-ce qu''une échographie Doppler ?","a":"C''est un examen indolore et sans danger qui utilise les ultrasons pour visualiser vos veines et artères et mesurer la circulation du sang. L''angiologue le réalise souvent en consultation pour évaluer varices, phlébite ou état des artères."},{"q":"Les varices sont-elles seulement un problème esthétique ?","a":"Non. Au-delà de l''aspect, les varices peuvent provoquer douleurs, lourdeurs et complications. L''angiologue évalue leur retentissement sur la circulation et propose une prise en charge adaptée, du traitement conservateur aux gestes spécialisés."}]', NULL, ARRAY['varices', 'jambes-lourdes', 'phlebite', 'maladie-de-raynaud']::text[], 'استشر طبيب الأوعية الدموية عند اضطرابات الأوردة والشرايين: الدوالي، ثقل الساقين أو تورّمها، الإحساس بالبرودة أو التنميل في الأطراف، أو الاشتباه في التهاب وريدي خثاري. بصفته اختصاصي الدورة الدموية، يفحص أوعيتك، غالباً بالصدى دوبلر، للوقاية من أمراض الأوعية والتكفّل بها.', 'دوالي أو أوردة ظاهرة مزعجة أو مؤلمة
ساقان ثقيلتان أو متورّمتان أو مؤلمتان في نهاية اليوم
إحساس بالبرودة أو أصابع تبيضّ (داء رينو)
متابعة الدورة الدموية في حالة السكري أو التدخين
صعوبة في المشي مع ألم في الساقين عند الجهد
متابعة بعد التهاب وريدي خثاري أو علاج وعائي', 'ساق دافئة وحمراء ومتورّمة ومؤلمة من جهة واحدة
ألم مفاجئ وبرودة في أحد الأطراف
جرح في القدم لا يلتئم، خاصة عند مريض السكري', 'احجز موعداً مع طبيب الأوعية الدموية عندما تصبح الدوالي مزعجة، أو عندما تكون ساقاك ثقيلتين أو متورّمتين بانتظام، أو لمراقبة دورتك الدموية إذا كنت مصاباً بالسكري أو مدخّناً أو معرّضاً لخطر وعائي. يتيح تقييم بالصدى دوبلر التدخّل المبكر. وفي حالة ساق دافئة وحمراء ومؤلمة فجأة، أو طرف بارد ومؤلم، استشر بشكل عاجل: فقد يكون التهاباً وريدياً خثارياً أو انسداداً.', '[{"q":"ما هو الصدى دوبلر؟","a":"هو فحص غير مؤلم وآمن يستخدم الموجات فوق الصوتية لرؤية أوردتك وشرايينك وقياس تدفّق الدم. غالباً ما يجريه طبيب الأوعية أثناء الاستشارة لتقييم الدوالي أو التهاب وريدي أو حالة الشرايين."},{"q":"هل الدوالي مجرّد مشكلة جمالية؟","a":"لا. إلى جانب المظهر، قد تسبّب الدوالي آلاماً وثقلاً ومضاعفات. يقيّم طبيب الأوعية تأثيرها على الدورة الدموية ويقترح تكفّلاً مناسباً، من العلاج المحافظ إلى التدخّلات المتخصّصة."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='angiologie'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_cardiologie', s."id", 'Consultez un cardiologue en cas de palpitations, d''essoufflement anormal, de douleurs thoraciques à l''effort, d''hypertension, ou pour un bilan si vous avez des facteurs de risque (tabac, diabète, cholestérol, antécédents familiaux). Une douleur thoracique intense est une urgence : appelez les secours.', 'Palpitations ou battements irréguliers
Essoufflement inhabituel à l''effort ou au repos
Douleur ou oppression thoracique à l''effort
Hypertension artérielle à évaluer ou à suivre
Bilan de facteurs de risque (tabac, diabète, cholestérol, hérédité)', 'Douleur thoracique intense, prolongée, irradiant au bras ou à la mâchoire (→ urgence)
Essoufflement brutal ou malaise avec sueurs
Perte de connaissance à l''effort', 'Pour un bilan ou un suivi, prenez rendez-vous de façon programmée, souvent sur orientation du médecin généraliste. Toute douleur thoracique évoquant un infarctus impose d''appeler immédiatement les secours.', '[{"q":"À partir de quel âge faire un bilan cardiaque ?","a":"Il n''y a pas d''âge unique : le médecin le propose selon vos facteurs de risque. Une hypertension ou un antécédent familial avancent l''échéance."},{"q":"Hypertension : généraliste ou cardiologue ?","a":"Le généraliste suit la plupart des hypertensions. Le cardiologue intervient pour les formes compliquées, résistantes ou avec retentissement."}]', NULL, ARRAY['hypertension-arterielle', 'angine-de-poitrine', 'palpitations', 'douleur-thoracique', 'hypercholesterolemie']::text[], 'استشِر طبيب القلب عند خفقان، ضيق تنفّس غير طبيعي، آلام صدرية عند المجهود، ارتفاع ضغط، أو لإجراء فحص إذا كانت لديك عوامل خطر (تدخين، سكري، كوليسترول، سوابق عائلية). الألم الصدري الشديد طارئ: اتّصل بالإسعاف.', 'خفقان أو نبضات غير منتظمة
ضيق تنفّس غير معتاد عند المجهود أو الراحة
ألم أو ضغط صدري عند المجهود
ارتفاع ضغط الدم للتقييم أو المتابعة
فحص عوامل الخطر (تدخين، سكري، كوليسترول، وراثة)', 'ألم صدري شديد ومطوّل يمتدّ إلى الذراع أو الفكّ (→ طوارئ)
ضيق تنفّس مفاجئ أو إغماء مع تعرّق
فقدان وعي أثناء المجهود', 'للفحص أو المتابعة، احجز موعداً مُبرمَجاً، غالباً بتوجيه من الطبيب العام. أيّ ألم صدري يُوحي باحتشاء يفرض الاتّصال بالإسعاف فوراً.', '[{"q":"من أيّ سنّ أُجري فحصاً للقلب؟","a":"لا يوجد سنّ وحيد: يقترحه الطبيب حسب عوامل الخطر لديك. يُقدّم ارتفاع الضغط أو سابقة عائلية هذا الموعد."},{"q":"ارتفاع الضغط: طبيب عام أم طبيب قلب؟","a":"يتابع الطبيب العام معظم حالات ارتفاع الضغط. يتدخّل طبيب القلب في الأشكال المُعقّدة أو المقاوِمة أو ذات المضاعفات."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='cardiologie'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_chirurgie-dentaire', s."id", 'Consultez un chirurgien-dentiste pour toute douleur dentaire, carie, gencive qui saigne, dent cassée ou abcès, ainsi que pour un contrôle et un détartrage réguliers. Le dentiste examine dents et gencives, traite les lésions et prévient les complications. Une visite régulière permet de dépister tôt les problèmes, souvent indolores au début.', 'Douleur dentaire, sensibilité au chaud, au froid ou au sucré
Carie visible, dent cassée, ébréchée ou plombage perdu
Gencives qui saignent, gonflent ou se rétractent
Douleur ou poussée difficile d''une dent de sagesse
Mauvaise haleine persistante malgré une bonne hygiène
Contrôle et détartrage réguliers de prévention', 'Gonflement du visage ou de la joue avec fièvre (abcès qui s''étend)
Douleur intense qui empêche de dormir ou de s''alimenter
Traumatisme avec dent expulsée ou fracture de la mâchoire', 'Hors urgence, prenez rendez-vous dès l''apparition d''une douleur, d''une sensibilité ou d''un saignement des gencives, et n''attendez pas que la gêne devienne permanente. Un contrôle au moins une fois par an, avec détartrage, permet de dépister caries et problèmes de gencives tôt. Les enfants doivent aussi bénéficier de contrôles réguliers.', '[{"q":"À quelle fréquence consulter le dentiste ?","a":"Un contrôle au moins une fois par an est recommandé, même sans douleur, avec un détartrage selon les besoins. Ce rythme peut être plus rapproché en cas de problèmes de gencives, de caries fréquentes ou sur avis du dentiste. Les enfants bénéficient aussi d''un suivi régulier."},{"q":"Faut-il attendre d''avoir mal pour consulter ?","a":"Non. De nombreux problèmes dentaires, comme les caries débutantes, sont indolores au début. Attendre la douleur signifie souvent une atteinte plus avancée. Les visites régulières permettent de traiter tôt, plus simplement, et d''éviter des soins lourds."}]', NULL, ARRAY['carie-dentaire', 'abces-dentaire', 'dent-de-sagesse', 'aphtes', 'bruxisme']::text[], 'استشر طبيب الأسنان عند أي ألم في الأسنان، تسوّس، نزيف لثة، سنّ مكسورة أو خرّاج، وكذلك للمراقبة وإزالة الجير بانتظام. يفحص الطبيب الأسنان واللثة، ويعالج الإصابات، ويقي من المضاعفات. الزيارة المنتظمة تتيح الكشف المبكر عن المشاكل التي غالبًا ما تكون بلا ألم في البداية.', 'ألم في الأسنان أو حساسية للحار أو البارد أو الحلو
تسوّس ظاهر أو سنّ مكسورة أو مشقوقة أو حشو مفقود
لثة تنزف أو تنتفخ أو تنحسر
ألم أو بزوغ صعب لضرس العقل
رائحة فم كريهة مستمرة رغم النظافة الجيدة
مراقبة وإزالة الجير بانتظام للوقاية', 'انتفاخ الوجه أو الخد مع حمّى (خرّاج يمتد)
ألم شديد يمنع النوم أو الأكل
رضّ مع سقوط سنّ أو كسر في الفك', 'خارج الحالات الطارئة، احجز موعدًا بمجرد ظهور ألم أو حساسية أو نزيف في اللثة، ولا تنتظر أن يصير الانزعاج دائمًا. المراقبة مرة في السنة على الأقل، مع إزالة الجير، تتيح الكشف المبكر عن التسوّس ومشاكل اللثة. ويحتاج الأطفال أيضًا إلى مراقبة منتظمة.', '[{"q":"كم مرة ينبغي زيارة طبيب الأسنان؟","a":"يُنصح بمراقبة مرة في السنة على الأقل، حتى دون ألم، مع إزالة الجير حسب الحاجة. وقد يكون الإيقاع أقرب عند مشاكل اللثة أو التسوّس المتكرر أو بناءً على رأي الطبيب. ويستفيد الأطفال أيضًا من متابعة منتظمة."},{"q":"هل ننتظر الألم قبل الاستشارة؟","a":"لا. كثير من مشاكل الأسنان، كالتسوّس المبكر، بلا ألم في البداية. وانتظار الألم يعني غالبًا إصابة أكثر تقدمًا. الزيارات المنتظمة تتيح العلاج مبكرًا وبأبسط طريقة وتجنّب علاجات ثقيلة."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='chirurgie-dentaire'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_chirurgie-generale', s."id", 'Le chirurgien généraliste est consulté, souvent sur adressage, pour évaluer et opérer des affections courantes de l''abdomen : hernie de l''aine, appendicite, calculs de la vésicule biliaire, kyste. Après un examen et parfois une imagerie, il détermine si une intervention est nécessaire et vous explique la marche à suivre.', 'Hernie de l''aine ou de l''abdomen gênante ou qui grossit
Calculs de la vésicule biliaire responsables de douleurs répétées
Avis chirurgical pour des douleurs abdominales persistantes
Kyste, abcès ou lésion nécessitant un geste chirurgical
Bilan avant une intervention programmée et suivi après opération
Nodule ou masse à explorer sur adressage du médecin', 'Douleur abdominale intense et brutale, surtout en bas à droite, avec fièvre
Ventre dur, gonflé et très douloureux avec arrêt des gaz et vomissements
Hernie soudain dure, douloureuse et impossible à réduire', 'On consulte le chirurgien généraliste le plus souvent après avoir été adressé par son médecin, pour une hernie, des calculs biliaires ou une masse à évaluer. Prenez rendez-vous sans tarder si une gêne s''installe ou s''aggrave, afin de discuter de l''intérêt d''une opération à froid. En revanche, une douleur abdominale violente et soudaine, avec fièvre ou vomissements, relève des urgences et non d''une consultation programmée.', '[{"q":"Une hernie de l''aine doit-elle toujours être opérée ?","a":"La chirurgie est souvent proposée pour une hernie de l''aine, car elle ne disparaît pas seule et peut se compliquer. Le moment de l''opération dépend de la gêne et du risque. Seul le chirurgien, après examen, peut poser l''indication et vous en expliquer les modalités."},{"q":"Douleur au ventre à droite : faut-il aller aux urgences ?","a":"Une douleur intense et brutale en bas à droite du ventre, surtout avec fièvre, nausées ou ventre dur, peut évoquer une urgence comme une appendicite. Dans ce cas, rendez-vous aux urgences sans attendre. Pour une gêne modérée et durable, parlez-en à votre médecin qui vous orientera."}]', NULL, ARRAY['appendicite', 'calculs-biliaires', 'hernie-hiatale']::text[], 'تتم استشارة الجرّاح العام، غالباً بتوجيه، لتقييم وعلاج أمراض شائعة في البطن: فتق المغبن، التهاب الزائدة الدودية، حصى المرارة، الكيس. بعد الفحص وأحياناً التصوير، يحدد ما إذا كان التدخل ضرورياً ويشرح لك الخطوات اللازمة.', 'فتق في المغبن أو البطن مزعج أو يكبر حجمه
حصى في المرارة تسبب آلاماً متكررة
رأي جراحي لآلام بطنية مستمرة
كيس أو خرّاج أو آفة تستلزم تدخلاً جراحياً
فحص قبل عملية مبرمجة ومتابعة بعد الجراحة
عقدة أو كتلة يجب استكشافها بتوجيه من الطبيب', 'ألم بطني شديد ومفاجئ، خاصة أسفل اليمين، مصحوب بحمّى
بطن صلب ومنتفخ ومؤلم جداً مع انقطاع الغازات وقيء
فتق أصبح فجأة صلباً ومؤلماً ويتعذّر إرجاعه', 'تتم استشارة الجرّاح العام في أغلب الأحيان بعد التوجيه من قبل طبيبك، من أجل فتق أو حصى في المرارة أو كتلة يجب تقييمها. احجز موعداً دون تأخير إذا استقرّ إزعاج أو تفاقم، لمناقشة جدوى عملية غير مستعجلة. أما الألم البطني العنيف والمفاجئ، مع حمّى أو قيء، فيندرج ضمن المستعجلات وليس ضمن استشارة مبرمجة.', '[{"q":"هل يجب دائماً إجراء عملية لفتق المغبن؟","a":"غالباً ما تُقترح الجراحة لفتق المغبن، لأنه لا يزول وحده وقد تحدث له مضاعفات. يتوقف توقيت العملية على درجة الإزعاج والخطر. وحده الجرّاح، بعد الفحص، يمكنه تحديد الحاجة وشرح تفاصيلها لك."},{"q":"ألم في البطن جهة اليمين: هل يجب التوجه إلى المستعجلات؟","a":"ألم شديد ومفاجئ أسفل يمين البطن، خاصة مع حمّى أو غثيان أو بطن صلب، قد يوحي بحالة طارئة مثل التهاب الزائدة الدودية. في هذه الحالة توجّه إلى المستعجلات دون انتظار. أما الإزعاج المعتدل والمستمر فتحدّث عنه مع طبيبك الذي سيوجّهك."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='chirurgie-generale'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_dermatologie', s."id", 'Consultez un dermatologue pour un problème de peau, de cheveux ou d''ongles qui dure, s''aggrave ou vous inquiète : bouton ou grain de beauté qui change, acné persistante, plaques, démangeaisons tenaces, chute de cheveux importante. Un médecin généraliste peut orienter en premier recours.', 'Grain de beauté qui change de forme, de couleur ou de taille
Acné persistante ou laissant des cicatrices
Plaques, rougeurs ou desquamation qui durent (eczéma, psoriasis)
Démangeaisons tenaces sans cause évidente
Chute de cheveux importante ou inhabituelle
Lésion, plaie ou verrue qui ne guérit pas', 'Grain de beauté qui saigne, gratte ou grossit rapidement
Plaie qui ne cicatrise pas depuis plusieurs semaines
Éruption étendue avec fièvre ou atteinte de l''état général', 'Pour un motif chronique, prenez rendez-vous sans urgence mais sans trop attendre : plus une lésion suspecte est vue tôt, mieux c''est. Devant un grain de beauté qui change, consultez rapidement.', '[{"q":"Faut-il une lettre du médecin traitant pour voir un dermatologue ?","a":"Au Maroc, vous pouvez consulter directement un dermatologue. Un médecin généraliste peut toutefois vous orienter et assurer le suivi."},{"q":"À quelle fréquence surveiller ses grains de beauté ?","a":"Une surveillance annuelle est raisonnable si vous avez de nombreux grains de beauté ou des antécédents ; consultez sans attendre si l''un d''eux change."}]', NULL, ARRAY['acne', 'eczema', 'psoriasis', 'demangeaisons', 'chute-de-cheveux', 'cancer-de-la-peau']::text[], 'استشِر طبيب الجلد لمشكلة في الجلد أو الشعر أو الأظافر تدوم أو تتفاقم أو تُقلقك: شامة تتغيّر، حبّ شباب مستمرّ، بُقع، حكّة عنيدة، تساقط شعر مهمّ. يمكن لطبيب عام التوجيه في أول استشارة.', 'شامة تتغيّر شكلاً أو لوناً أو حجماً
حبّ شباب مستمرّ أو يُخلّف ندوباً
بُقع أو احمرار أو تقشّر يدوم (إكزيما، صدفية)
حكّة عنيدة دون سبب واضح
تساقط شعر مهمّ أو غير معتاد
آفة أو جُرح أو ثؤلول لا يلتئم', 'شامة تنزف أو تحكّ أو تكبر بسرعة
جُرح لا يلتئم منذ عدّة أسابيع
طفح واسع مع حُمّى أو تدهور الحالة العامّة', 'لسبب مزمن، احجز موعداً دون استعجال لكن دون تأخير كبير: كلّما رُئيت آفة مشبوهة مبكراً كان أفضل. أمام شامة تتغيّر، استشِر بسرعة.', '[{"q":"هل تلزم رسالة من الطبيب المعالِج لرؤية طبيب الجلد؟","a":"بالمغرب يمكنك استشارة طبيب الجلد مباشرةً. غير أنّ طبيباً عاماً يمكنه توجيهك وضمان المتابعة."},{"q":"كم مرّة أراقب شاماتي؟","a":"المراقبة السنوية معقولة إذا كانت لديك شامات كثيرة أو سوابق؛ استشِر دون تأخير إذا تغيّرت إحداها."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='dermatologie'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_endocrinologie-et-maladies-metaboliques', s."id", 'Consultez un endocrinologue pour un trouble hormonal ou métabolique : diabète, maladie de la thyroïde, nodule au cou, prise ou perte de poids inexpliquée, fatigue liée aux hormones, troubles du cholestérol ou anomalies découvertes sur une prise de sang. L''endocrinologue interprète le bilan, recherche la cause et organise le suivi adapté.', 'Diabète à équilibrer ou glycémie élevée découverte lors d''un bilan
Signes de thyroïde perturbée : fatigue, frilosité, nervosité, palpitations
Nodule ou gonflement à la base du cou (goitre)
Prise ou perte de poids inexpliquée malgré des habitudes stables
Anomalies persistantes du cholestérol ou du bilan métabolique
Troubles hormonaux : pilosité, cycles, croissance ou puberté anormale', 'Soif intense, urines très abondantes et amaigrissement rapide
Palpitations fortes avec amaigrissement, tremblements et grande agitation
Malaise avec sueurs, confusion ou perte de connaissance chez un diabétique', 'Hors urgence, prenez rendez-vous quand une prise de sang révèle une anomalie hormonale ou métabolique, quand des symptômes évocateurs durent, ou pour organiser le suivi d''un diabète ou d''une thyroïde. Votre médecin généraliste assure souvent le premier bilan et vous adresse à l''endocrinologue pour les situations complexes ou spécialisées.', '[{"q":"Diabète : généraliste ou endocrinologue ?","a":"Un diabète stable est souvent suivi par le médecin généraliste. L''endocrinologue intervient pour les situations plus complexes : équilibre difficile, complications, grossesse ou traitement à ajuster. Les deux travaillent en coordination ; votre médecin vous oriente selon votre profil."},{"q":"Un nodule de la thyroïde est-il inquiétant ?","a":"La plupart des nodules thyroïdiens sont bénins, mais tout nodule mérite une évaluation. L''endocrinologue examine, prescrit les examens utiles et décide d''une simple surveillance ou d''un bilan plus poussé. Consultez sans tarder si le nodule grossit vite ou gêne pour avaler."}]', NULL, ARRAY['diabete', 'carence-en-vitamine-d', 'hypercholesterolemie', 'diabete-gestationnel']::text[], 'استشر طبيب الغدد لأي اضطراب هرموني أو استقلابي: السكري، أمراض الغدة الدرقية، عقدة في الرقبة، زيادة أو نقص وزن غير مبرّر، تعب مرتبط بالهرمونات، اضطرابات الكوليسترول أو خلل يُكتشف في تحليل الدم. يفسّر طبيب الغدد النتائج ويبحث عن السبب وينظّم المتابعة المناسبة.', 'سكري يحتاج إلى ضبط أو ارتفاع سكر يُكتشف في تحليل
علامات خلل الغدة الدرقية: تعب، برودة، عصبية، خفقان
عقدة أو انتفاخ في قاعدة الرقبة (تضخم الغدة)
زيادة أو نقص وزن غير مبرّر رغم ثبات العادات
خلل مستمر في الكوليسترول أو التحليل الاستقلابي
اضطرابات هرمونية: الشعر، الدورة، النمو أو بلوغ غير طبيعي', 'عطش شديد وبول غزير جدًا ونقص وزن سريع
خفقان قوي مع نقص وزن ورعشة وهياج شديد
إغماء مع تعرّق أو تشوّش أو فقدان وعي عند مريض السكري', 'خارج الحالات الطارئة، احجز موعدًا حين يكشف تحليل دم عن خلل هرموني أو استقلابي، أو حين تستمر أعراض موحية، أو لتنظيم متابعة السكري أو الغدة الدرقية. غالبًا ما يقوم طبيبك العام بالفحص الأولي ويحوّلك إلى طبيب الغدد للحالات المعقّدة أو المتخصصة.', '[{"q":"السكري: طبيب عام أم طبيب غدد؟","a":"غالبًا ما يتابع الطبيب العام السكري المستقر. ويتدخل طبيب الغدد في الحالات الأعقد: صعوبة الضبط، المضاعفات، الحمل أو تعديل العلاج. ويعمل الطبيبان بتنسيق؛ ويوجّهك طبيبك حسب حالتك."},{"q":"هل عقدة الغدة الدرقية مدعاة للقلق؟","a":"معظم عقد الغدة الدرقية حميدة، لكن كل عقدة تستحق تقييمًا. يفحص طبيب الغدد ويطلب الفحوص المفيدة ويقرر مراقبة بسيطة أو فحصًا أعمق. استشر دون تأخير إذا كبرت العقدة بسرعة أو أعاقت البلع."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='endocrinologie-et-maladies-metaboliques'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_gastro-enterologie', s."id", 'Consultez un gastro-entérologue pour des troubles digestifs qui durent : douleurs abdominales, brûlures d''estomac fréquentes, transit perturbé, ballonnements persistants, ou pour un dépistage (côlon) selon l''âge et les antécédents. Un saignement digestif ou une douleur intense justifie une consultation rapide.', 'Brûlures d''estomac ou remontées fréquentes
Douleurs abdominales récurrentes
Transit durablement perturbé (diarrhée, constipation)
Ballonnements persistants ou inconfort digestif
Dépistage du cancer colorectal selon l''âge et les antécédents', 'Sang dans les selles ou selles noires
Perte de poids inexpliquée, difficulté à avaler
Douleur abdominale intense et brutale', 'Des symptômes qui durent plus de quelques semaines justifient un rendez-vous, souvent après un premier avis du généraliste. Un saignement ou des signes d''alerte imposent de consulter rapidement.', '[{"q":"Quand faire une coloscopie de dépistage ?","a":"Le médecin propose le dépistage selon votre âge et vos antécédents familiaux ; il ne se décide pas seul et dépend de chaque situation."},{"q":"Brûlures d''estomac occasionnelles : faut-il consulter ?","a":"Des brûlures rares s''améliorent souvent avec des mesures simples. Si elles deviennent fréquentes ou gênantes, consultez."}]', NULL, ARRAY['brulures-d-estomac', 'mal-de-ventre', 'ballonnements', 'constipation', 'diarrhee', 'hemorroides']::text[], 'استشِر طبيب الجهاز الهضمي لاضطرابات هضمية تدوم: آلام بطنية، حُرقة معدة متكرّرة، اضطراب العبور، انتفاخ مستمرّ، أو للكشف (القولون) حسب السنّ والسوابق. النزيف الهضمي أو الألم الشديد يستوجب استشارة سريعة.', 'حُرقة معدة أو ارتجاع متكرّر
آلام بطنية متكرّرة
اضطراب دائم في العبور (إسهال، إمساك)
انتفاخ مستمرّ أو انزعاج هضمي
الكشف عن سرطان القولون والمستقيم حسب السنّ والسوابق', 'دم في البراز أو براز أسود
فقدان وزن غير مُفسَّر، صعوبة في البلع
ألم بطني شديد ومفاجئ', 'الأعراض التي تدوم أكثر من بضعة أسابيع تستوجب موعداً، غالباً بعد رأي أوّلي من الطبيب العام. النزيف أو علامات الإنذار تفرض استشارة سريعة.', '[{"q":"متى أُجري تنظير قولون للكشف؟","a":"يقترح الطبيب الكشف حسب سنّك وسوابقك العائلية؛ لا يُقرَّر وحده ويعتمد على كلّ حالة."},{"q":"حُرقة معدة عابرة: هل أستشير؟","a":"الحُرقة النادرة تتحسّن غالباً بتدابير بسيطة. إذا صارت متكرّرة أو مُزعجة، استشِر."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='gastro-enterologie'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_geriatrie', s."id", 'Consultez un gériatre pour la santé de la personne âgée : troubles de la mémoire, chutes à répétition, perte d''autonomie, plusieurs maladies ou traitements à coordonner, dénutrition ou fragilité. Le gériatre réalise une évaluation globale, ajuste la prise en charge et aide à préserver l''autonomie et la qualité de vie au quotidien.', 'Troubles de la mémoire ou changements de comportement chez un aîné
Chutes à répétition ou perte d''équilibre
Perte d''autonomie progressive dans les gestes du quotidien
Plusieurs maladies et traitements à coordonner et à alléger
Perte d''appétit, amaigrissement ou dénutrition
Bilan de fragilité pour préserver l''autonomie', 'Chute avec traumatisme, impossibilité de se relever ou confusion soudaine
Désorientation brutale, fièvre ou baisse de vigilance inhabituelle
Refus de manger et de boire avec affaiblissement rapide', 'Hors urgence, prenez rendez-vous quand une personne âgée cumule troubles de la mémoire, chutes, perte de poids ou d''autonomie, ou de nombreux traitements. Votre médecin généraliste assure le suivi habituel et vous oriente vers le gériatre pour une évaluation globale, un avis sur les traitements ou l''organisation du maintien à domicile.', '[{"q":"Quand consulter un gériatre plutôt que le généraliste ?","a":"Le généraliste reste le premier recours. Le gériatre apporte une évaluation globale quand plusieurs problèmes se cumulent : mémoire, chutes, dénutrition, autonomie, traitements multiples. Les deux travaillent ensemble pour adapter la prise en charge à la personne âgée."},{"q":"Les pertes de mémoire liées à l''âge sont-elles normales ?","a":"De légers oublis peuvent accompagner l''âge, mais des troubles qui s''aggravent, gênent le quotidien ou inquiètent l''entourage méritent une évaluation. Le gériatre distingue le vieillissement normal d''un trouble à explorer et propose un accompagnement adapté."}]', NULL, ARRAY['demence', 'denutrition', 'carence-en-vitamine-d']::text[], 'استشر طبيب الشيخوخة لصحة المسنّ: اضطرابات الذاكرة، السقوط المتكرر، فقدان الاستقلالية، تعدّد الأمراض أو العلاجات التي تحتاج تنسيقًا، سوء التغذية أو الهشاشة. يجري الطبيب تقييمًا شاملاً، ويعدّل الرعاية، ويساعد على الحفاظ على الاستقلالية وجودة الحياة اليومية.', 'اضطرابات ذاكرة أو تغيّرات سلوكية عند المسنّ
سقوط متكرر أو فقدان التوازن
فقدان تدريجي للاستقلالية في أعمال الحياة اليومية
تعدّد الأمراض والعلاجات التي تحتاج تنسيقًا وتخفيفًا
فقدان الشهية أو نقص الوزن أو سوء التغذية
تقييم الهشاشة للحفاظ على الاستقلالية', 'سقوط مع رضّ أو استحالة النهوض أو تشوّش مفاجئ
تشوّش مفاجئ أو حمّى أو انخفاض غير معتاد في اليقظة
رفض الأكل والشرب مع ضعف سريع', 'خارج الحالات الطارئة، احجز موعدًا حين يجمع المسنّ بين اضطرابات الذاكرة والسقوط ونقص الوزن أو الاستقلالية، أو تعدّد العلاجات. يضمن طبيبك العام المتابعة المعتادة ويوجّهك إلى طبيب الشيخوخة لتقييم شامل، أو رأي حول العلاجات، أو تنظيم البقاء في المنزل.', '[{"q":"متى نستشير طبيب الشيخوخة بدل الطبيب العام؟","a":"يبقى الطبيب العام أول جهة رعاية. ويقدّم طبيب الشيخوخة تقييمًا شاملاً حين تتراكم عدة مشاكل: الذاكرة، السقوط، سوء التغذية، الاستقلالية، تعدّد العلاجات. ويعمل الطبيبان معًا لتكييف الرعاية مع المسنّ."},{"q":"هل فقدان الذاكرة المرتبط بالسنّ أمر طبيعي؟","a":"قد يرافق نسيان خفيف تقدّم السنّ، لكن الاضطرابات التي تتفاقم أو تعيق الحياة اليومية أو تقلق المحيطين تستحق تقييمًا. ويميّز طبيب الشيخوخة بين الشيخوخة الطبيعية واضطراب يحتاج استكشافًا، ويقترح مرافقة مناسبة."}]', NULL, now(), now(), 'PUBLISHED', now()
FROM "specialties" s WHERE s."slug"='geriatrie'
ON CONFLICT ("specialtyId") DO UPDATE SET "shortAnswer"=EXCLUDED."shortAnswer", "reasons"=EXCLUDED."reasons", "redFlags"=EXCLUDED."redFlags", "whenToConsult"=EXCLUDED."whenToConsult", "faqJson"=EXCLUDED."faqJson", "sources"=EXCLUDED."sources", "relatedSlugs"=EXCLUDED."relatedSlugs", "shortAnswerAr"=EXCLUDED."shortAnswerAr", "reasonsAr"=EXCLUDED."reasonsAr", "redFlagsAr"=EXCLUDED."redFlagsAr", "whenToConsultAr"=EXCLUDED."whenToConsultAr", "faqJsonAr"=EXCLUDED."faqJsonAr", "sourcesAr"=EXCLUDED."sourcesAr", "reviewedAt"=EXCLUDED."reviewedAt", "arReviewedAt"=EXCLUDED."arReviewedAt", "updatedAt"=now();
INSERT INTO "specialty_guides" ("id","specialtyId","shortAnswer","reasons","redFlags","whenToConsult","faqJson","sources","relatedSlugs","shortAnswerAr","reasonsAr","redFlagsAr","whenToConsultAr","faqJsonAr","sourcesAr","reviewedAt","arReviewedAt","status","updatedAt")
SELECT 'sg_gyneco-obstetrique', s."id", 'Consultez un gynécologue pour le suivi gynécologique régulier, la contraception, des règles douloureuses ou irrégulières, des douleurs pelviennes, le suivi de grossesse, ou tout symptôme inhabituel. Un dépistage régulier (frottis) fait partie de la prévention. Certains symptômes justifient une consultation rapide.', 'Suivi gynécologique et dépistage réguliers
Contraception : choix et suivi
Règles douloureuses, absentes ou irrégulières
Douleurs pelviennes ou pertes inhabituelles
Suivi de grossesse', 'Saignements abondants ou en dehors des règles
Douleur pelvienne intense et brutale
Fièvre avec douleurs pelviennes', 'Un suivi et un dépistage réguliers sont recommandés même sans symptôme. Devant une douleur intense, une fièvre ou des saignements anormaux, consultez rapidement.', '[{"q":"À quelle fréquence faire un suivi gynécologique ?","a":"Un suivi régulier est conseillé ; le rythme du dépistage (frottis) est précisé par le médecin selon votre âge et vos antécédents."},{"q":"Peut-on consulter une sage-femme plutôt qu''un gynécologue ?","a":"La sage-femme assure le suivi gynécologique de prévention et la contraception chez la femme en bonne santé, et oriente si besoin."}]', NULL, ARRAY['absence-de-regles', 'mycose-vaginale', 'contraception', 'douleur-au-sein', 'diabete-gestationnel']::text[], 'استشِري طبيب النساء للمتابعة النسائية المنتظمة، وسائل منع الحمل، دورة مؤلمة أو غير منتظمة، آلام حوضية، متابعة الحمل، أو أيّ عَرَض غير معتاد. الكشف المنتظم جزء من الوقاية. بعض الأعراض تستوجب استشارة سريعة.', 'متابعة نسائية وكشف منتظمان
وسائل منع الحمل: الاختيار والمتابعة
دورة مؤلمة أو غائبة أو غير منتظمة
آلام حوضية أو إفرازات غير معتادة
متابعة الحمل', 'نزيف غزير أو خارج فترة الدورة
ألم حوضي شديد ومفاجئ
حُمّى مع آلام حوضية', 'يُنصَح بمتابعة وكشف منتظمين حتى دون أعراض. أمام ألم شديد أو حُمّى أو نزيف غير طبيعي، استشيري بسرعة.', '[{"q":"كم مرّة أُجري متابعة نسائية؟","a":"يُنصَح بمتابعة منتظمة؛ يحدّد الطبيب وتيرة الكشف حسب سنّك وسوابقك."},{"q":"هل يمكن استشارة قابلة بدل طبيب النساء؟","a":"تضمن القابلة المتابعة النسائية الوقائية ووسائل منع الحمل لدى المرأة السليمة، وتوجّه عند الحاجة."}]', NULL, now(), now(), 'PUBLISHED', now()
